values ('fq_conc_058', 'The Harbinger''s Shadow', 'story', 'S', 'CONCORDIUM', 'VOID_ECHO_CHASM', 'Intelligence confirms: the Abyss Harbinger is awakening. (Location: Void Echo Chasm, Officer Valen) Its shadow already corrupts the deepest chasm. Prepare for the final confrontation.', '{"npc_id": "npc_concordium_officer", "name": "", "location": "VOID_ECHO_CHASM"}'::jsonb, '{"min_level": 57, "reputation_required": 180, "required_quests": ["fq_conc_057"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_ABYSSAL_REAVER", "count": 6, "description": "Cut through the Harbinger''s Abyssal vanguard. [Aethel Abyssal Reaver]"}, {"type": "kill", "target": "CHRONO_WRAITH", "count": 1, "description": "Defeat a Chrono Wraith guarding the Harbinger''s sanctum."}, {"type": "collect", "target": "core_fragment", "count": 1, "description": "Collect core fragment (x1). [Item: Core Fragment]"}]'::jsonb, '{"exp": 7500, "currency": 3800, "crd": 1900, "rep": 2400, "items": [{"item_id": "event_horizon_fragment_l", "quantity": 1}], "reputation": 50}'::jsonb, false, false, 'fq_conc_059', false, NULL, NULL, NULL, 'quest_concordium.json', 57)
