values ('fq_conc_059', 'Soul Harvest', 'boss', 'S', 'CONCORDIUM', 'VOID_ECHO_CHASM', 'Soul Fragmenters have multiplied throughout the chasm. (Location: Void Echo Chasm, Officer Valen) Each one harvested strengthens the Harbinger. The harvest must end.', '{"npc_id": "npc_concordium_officer", "name": "", "location": "VOID_ECHO_CHASM"}'::jsonb, '{"min_level": 58, "reputation_required": 3420, "required_quests": ["fq_conc_058"]}'::jsonb, '[{"type": "kill", "target": "SOUL_FRAGMENTER", "count": 3, "description": "Destroy three Soul Fragmenters."}, {"type": "kill", "target": "VOID_STALKER", "count": 1, "description": "Eliminate a Void Stalker protecting the Fragmenters."}]'::jsonb, '{"exp": 8000, "currency": 4000, "crd": 2000, "rep": 2500, "items": [{"item_id": "brainwave_oscillator", "quantity": 1}], "reputation": 50}'::jsonb, false, false, 'fq_conc_060', false, NULL, NULL, NULL, 'quest_concordium.json', 58)
