values ('fq_conc_061', 'Severance Faultline', 'exploration', 'S', 'CONCORDIUM', 'SEVERANCE_FAULTLINE', 'After the Harbinger''s fall, seismic readings spike across Xylos. The Severance Faultline threatens to tear the planet apart. Investigate immediately. Quest giver: Officer Valen at Nexus Core Command Post.', '{"npc_id": "npc_concordium_officer", "name": "", "location": "SEVERANCE_FAULTLINE"}'::jsonb, '{"min_level": 60, "reputation_required": 3540, "required_quests": ["fq_conc_060"]}'::jsonb, '[{"type": "travel", "target": "SEVERANCE_FAULTLINE", "count": 1, "description": "Enter the Severance Faultline."}, {"type": "collect", "target": "stinger_core", "count": 3, "description": "Collect stinger core (x3). [Item: Stinger Core]"}]'::jsonb, '{"exp": 5000, "currency": 2500, "crd": 1250, "rep": 1600, "items": [{"item_id": "stabilizer_gyro_unit", "quantity": 2}], "reputation": 50}'::jsonb, false, false, 'fq_conc_062', false, NULL, NULL, NULL, 'quest_concordium.json', 60)
