values ('fq_conc_062', 'Fault Patrollers', 'hunt', 'S', 'CONCORDIUM', 'SEVERANCE_FAULTLINE', 'Aethel Iron Carapaces swarm the faultline, drawn by tectonic energy. (Location: Severance Faultline, Officer Valen) Clear them before they destabilize the plate boundaries.', '{"npc_id": "npc_concordium_officer", "name": "", "location": "SEVERANCE_FAULTLINE"}'::jsonb, '{"min_level": 61, "reputation_required": 3600, "required_quests": ["fq_conc_061"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_IRON_CARAPACE", "count": 8, "description": "Defeat Aethel Iron Carapaces along the faultline."}, {"type": "collect", "target": "carapace_fragment", "count": 3, "description": "Collect carapace fragment (x3). [Item: Carapace Fragment]"}]'::jsonb, '{"exp": 5200, "currency": 2600, "crd": 1300, "rep": 1700, "items": [{"item_id": "gravity_well_core", "quantity": 1}], "reputation": 50}'::jsonb, false, false, 'fq_conc_063', false, NULL, NULL, NULL, 'quest_concordium.json', 61)
