values ('fq_conc_063', 'Tyrant Fault', 'boss', 'S', 'CONCORDIUM', 'SEVERANCE_FAULTLINE', 'Crystal Tyrants are exploiting the unstable terrain. (Location: Severance Faultline, Officer Valen) Their crystal resonance amplifies the seismic chaos. Break them.', '{"npc_id": "npc_concordium_officer", "name": "", "location": "SEVERANCE_FAULTLINE"}'::jsonb, '{"min_level": 62, "reputation_required": 3660, "required_quests": ["fq_conc_062"]}'::jsonb, '[{"type": "kill", "target": "CRYSTAL_TYRANT", "count": 2, "description": "Defeat Crystal Tyrants at the fault''s epicenter."}, {"type": "kill", "target": "AETHEL_ABYSSAL_REAVER", "count": 4, "description": "Clear Abyssal Reavers drawn to the Tyrants energy. [Aethel Abyssal Reaver]"}]'::jsonb, '{"exp": 6000, "currency": 3000, "crd": 1500, "rep": 2000, "items": [{"item_id": "quantum_distortion_stone", "quantity": 2}], "reputation": 50}'::jsonb, false, false, 'fq_conc_064', false, NULL, NULL, NULL, 'quest_concordium.json', 62)
