values ('fq_conc_064', 'Jotunn Migration', 'boss', 'S', 'CONCORDIUM', 'SEVERANCE_FAULTLINE', 'Gigantic Jotunns are migrating through the faultline zone, crushing everything in their path. (Location: Severance Faultline, Officer Valen) Redirect or destroy them.', '{"npc_id": "npc_concordium_officer", "name": "", "location": "SEVERANCE_FAULTLINE"}'::jsonb, '{"min_level": 63, "reputation_required": 3720, "required_quests": ["fq_conc_063"]}'::jsonb, '[{"type": "kill", "target": "GIGANTIC_JOTUNN", "count": 3, "description": "Defeat Jotunns migrating through the faultline. [Gigantic Jotunn]"}, {"type": "collect", "target": "monster_material", "count": 1, "description": "Collect monster material (x1). [Item: Monster Material]"}]'::jsonb, '{"exp": 6500, "currency": 3300, "crd": 1650, "rep": 2100, "items": [{"item_id": "titan_core", "quantity": 2}], "reputation": 50}'::jsonb, false, false, 'fq_conc_065', false, NULL, NULL, NULL, 'quest_concordium.json', 63)
