values ('fq_conc_065', 'Siphon Approach', 'exploration', 'S', 'CONCORDIUM', 'AETHEL_SIPHON_CORE', 'The Aethel Siphon Core — a planetary stabilizer built by the Precursors — is failing. Enter the Core and assess the damage. Quest giver: Officer Valen at Nexus Core Command Post.', '{"npc_id": "npc_concordium_officer", "name": "", "location": "AETHEL_SIPHON_CORE"}'::jsonb, '{"min_level": 64, "reputation_required": 3780, "required_quests": ["fq_conc_064"]}'::jsonb, '[{"type": "travel", "target": "AETHEL_SIPHON_CORE", "count": 1, "description": "Enter the Aethel Siphon Core."}, {"type": "collect", "target": "thick_hide", "count": 2, "description": "Collect thick hide (x2). [Item: Thick Hide]"}]'::jsonb, '{"exp": 5500, "currency": 2800, "crd": 1400, "rep": 1800, "items": [{"item_id": "power_regulator_core", "quantity": 1}], "reputation": 50}'::jsonb, false, false, 'fq_conc_066', false, NULL, NULL, NULL, 'quest_concordium.json', 64)
