values ('fq_conc_066', 'Core Defense', 'hunt', 'S', 'CONCORDIUM', 'AETHEL_SIPHON_CORE', 'Hostile entities have infested the Siphon Core. (Location: Aethel Siphon Core, Officer Valen) They must be purged before repair operations can begin.', '{"npc_id": "npc_concordium_officer", "name": "", "location": "AETHEL_SIPHON_CORE"}'::jsonb, '{"min_level": 65, "reputation_required": 3840, "required_quests": ["fq_conc_065"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_ABYSSAL_REAVER", "count": 8, "description": "Purge Abyssal Reavers from the Core. [Aethel Abyssal Reaver]"}, {"type": "kill", "target": "AETHEL_VOID_CHANNELER", "count": 5, "description": "Eliminate Void Channelers corrupting the Core. [Aethel Void Channeler]"}]'::jsonb, '{"exp": 5800, "currency": 2900, "crd": 1450, "rep": 1900, "items": [{"item_id": "aethel_core_shard", "quantity": 3}], "reputation": 50}'::jsonb, false, false, 'fq_conc_067', false, NULL, NULL, NULL, 'quest_concordium.json', 65)
