values ('fq_conc_067', 'Corrupted Behemoth Siege', 'boss', 'S', 'CONCORDIUM', 'AETHEL_SIPHON_CORE', 'Corrupted Behemoths are assaulting the Siphon Core''s primary conduits. (Location: Aethel Siphon Core, Officer Valen) If the conduits fall, the Core goes critical.', '{"npc_id": "npc_concordium_officer", "name": "", "location": "AETHEL_SIPHON_CORE"}'::jsonb, '{"min_level": 66, "reputation_required": 3900, "required_quests": ["fq_conc_066"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_CORRUPTED_BEHEMOTH", "count": 3, "description": "Defeat Corrupted Behemoths at the primary conduits. [Aethel Corrupted Behemoth]"}, {"type": "collect", "target": "crystal_core", "count": 1, "description": "Collect crystal core (x1). [Item: Crystal Core]"}]'::jsonb, '{"exp": 6200, "currency": 3100, "crd": 1550, "rep": 2000, "items": [{"item_id": "corrupted_synapse_cluster", "quantity": 2}], "reputation": 50}'::jsonb, false, false, 'fq_conc_068', false, NULL, NULL, NULL, 'quest_concordium.json', 66)
