values ('fq_conc_068', 'Rift Closure', 'boss', 'S', 'CONCORDIUM', 'AETHEL_SIPHON_CORE', 'Aethel Rift Stalkers are opening micro-rifts inside the Core. (Location: Aethel Siphon Core, Officer Valen) Close the rifts and eliminate the Stalkers before containment fails.', '{"npc_id": "npc_concordium_officer", "name": "", "location": "AETHEL_SIPHON_CORE"}'::jsonb, '{"min_level": 67, "reputation_required": 3960, "required_quests": ["fq_conc_067"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_RIFT_STALKER", "count": 6, "description": "Defeat Rift Stalkers near the micro-rifts. [Aethel Rift Stalker]"}, {"type": "kill", "target": "CRYSTAL_TYRANT", "count": 1, "description": "Defeat a Crystal Tyrant guarding the main rift."}]'::jsonb, '{"exp": 6400, "currency": 3200, "crd": 1600, "rep": 2100, "items": [{"item_id": "dark_energy_fragment", "quantity": 3}], "reputation": 50}'::jsonb, false, false, 'fq_conc_069', false, NULL, NULL, NULL, 'quest_concordium.json', 67)
