values ('fq_conc_069', 'Titan''s Awakening', 'story', 'S', 'CONCORDIUM', 'AETHEL_SIPHON_CORE', 'The seismic data is clear: the Gravity Titan stirs beneath the Cradle Expanse. (Location: Aethel Siphon Core, Officer Valen) Its awakening is linked to the Siphon Core failure. Prepare for the worst.', '{"npc_id": "npc_concordium_officer", "name": "", "location": "AETHEL_SIPHON_CORE"}'::jsonb, '{"min_level": 68, "reputation_required": 230, "required_quests": ["fq_conc_068"]}'::jsonb, '[{"type": "collect", "target": "core_fragment", "count": 3, "description": "Collect core fragment (x3). [Item: Core Fragment]"}, {"type": "kill", "target": "GIGANTIC_JOTUNN", "count": 1, "description": "Defeat a Jotunn drawn by the Titan''s awakening call. [Gigantic Jotunn]"}]'::jsonb, '{"exp": 7000, "currency": 3500, "crd": 1750, "rep": 2200, "items": [{"item_id": "gravity_well_core", "quantity": 2}], "reputation": 50}'::jsonb, false, false, 'fq_conc_070', false, NULL, NULL, NULL, 'quest_concordium.json', 68)
