values ('fq_conc_071', 'Prima Materia', 'exploration', 'S', 'CONCORDIUM', 'PRIMA_MATERIA_FORGE', 'The Gravity Titan''s defeat has revealed the entrance to the Prima Materia Forge — the Precursor facility where pure matter is shaped. Claim it for Concordium. Quest giver: Officer Valen at Nexus Core Command Post.', '{"npc_id": "npc_concordium_officer", "name": "", "location": "PRIMA_MATERIA_FORGE"}'::jsonb, '{"min_level": 70, "reputation_required": 4140, "required_quests": ["fq_conc_070"]}'::jsonb, '[{"type": "travel", "target": "PRIMA_MATERIA_FORGE", "count": 1, "description": "Enter the Prima Materia Forge."}, {"type": "collect", "target": "void_channeler_core", "count": 2, "description": "Collect void channeler core (x2). [Item: Void Channeler Core]"}]'::jsonb, '{"exp": 6000, "currency": 3000, "crd": 1500, "rep": 2000, "items": [{"item_id": "raw_aethel_core", "quantity": 2}], "reputation": 50}'::jsonb, false, false, 'fq_conc_072', false, NULL, NULL, NULL, 'quest_concordium.json', 70)
