values ('fq_conc_072', 'Forge Guardians', 'hunt', 'S', 'CONCORDIUM', 'PRIMA_MATERIA_FORGE', 'The Forge has ancient automated defenses. (Location: Prima Materia Forge, Officer Valen) Disable them systematically — but beware rival faction scavengers.', '{"npc_id": "npc_concordium_officer", "name": "", "location": "PRIMA_MATERIA_FORGE"}'::jsonb, '{"min_level": 71, "reputation_required": 4200, "required_quests": ["fq_conc_071"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_IRON_CARAPACE", "count": 8, "description": "Destroy Forge defense automatons. [Aethel Iron Carapace]"}, {"type": "kill", "target": "AETHEL_RIFT_STALKER", "count": 4, "description": "Eliminate rival faction scavengers. [Aethel Rift Stalker]"}]'::jsonb, '{"exp": 6200, "currency": 3100, "crd": 1550, "rep": 2100, "items": [{"item_id": "rusted_cybernetic_arm", "quantity": 2}], "reputation": 50}'::jsonb, false, false, 'fq_conc_073', false, NULL, NULL, NULL, 'quest_concordium.json', 71)
