values ('fq_conc_073', 'Behemoth Foundry', 'boss', 'S', 'CONCORDIUM', 'PRIMA_MATERIA_FORGE', 'Corrupted Behemoths have been drawn to the Forge''s energy signature. (Location: Prima Materia Forge, Officer Valen) They must be purged before they consume the Prima Materia.', '{"npc_id": "npc_concordium_officer", "name": "", "location": "PRIMA_MATERIA_FORGE"}'::jsonb, '{"min_level": 72, "reputation_required": 4260, "required_quests": ["fq_conc_072"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_CORRUPTED_BEHEMOTH", "count": 3, "description": "Purge Corrupted Behemoths from the Forge. [Aethel Corrupted Behemoth]"}, {"type": "collect", "target": "crystal_core", "count": 2, "description": "Collect crystal core (x2). [Item: Crystal Core]"}]'::jsonb, '{"exp": 6500, "currency": 3300, "crd": 1650, "rep": 2200, "items": [{"item_id": "neural_disruptor_module", "quantity": 1}], "reputation": 50}'::jsonb, false, false, 'fq_conc_074', false, NULL, NULL, NULL, 'quest_concordium.json', 72)
