values ('fq_conc_074', 'Abyssal Forge', 'hunt', 'S', 'CONCORDIUM', 'PRIMA_MATERIA_FORGE', 'Abyssal Reavers are trying to corrupt the Forge''s core. (Location: Prima Materia Forge, Officer Valen) The Abyss must not claim the Prima Materia.', '{"npc_id": "npc_concordium_officer", "name": "", "location": "PRIMA_MATERIA_FORGE"}'::jsonb, '{"min_level": 73, "reputation_required": 4320, "required_quests": ["fq_conc_073"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_ABYSSAL_REAVER", "count": 8, "description": "Exterminate Abyssal Reavers in the Forge. [Aethel Abyssal Reaver]"}, {"type": "collect", "target": "void_channeler_core", "count": 3, "description": "Collect void channeler core (x3). [Item: Void Channeler Core]"}]'::jsonb, '{"exp": 6800, "currency": 3400, "crd": 1700, "rep": 2300, "items": [{"item_id": "aethel_fragment", "quantity": 3}], "reputation": 50}'::jsonb, false, false, 'fq_conc_075', false, NULL, NULL, NULL, 'quest_concordium.json', 73)
