values ('fq_conc_075', 'Jotunn Forge-Masters', 'boss', 'S', 'CONCORDIUM', 'PRIMA_MATERIA_FORGE', 'Gigantic Jotunns have claimed the deepest forge chambers as their territory. (Location: Prima Materia Forge, Officer Valen) These creatures wield the Forge''s heat as a weapon.', '{"npc_id": "npc_concordium_officer", "name": "", "location": "PRIMA_MATERIA_FORGE"}'::jsonb, '{"min_level": 74, "reputation_required": 4380, "required_quests": ["fq_conc_074"]}'::jsonb, '[{"type": "kill", "target": "GIGANTIC_JOTUNN", "count": 3, "description": "Defeat Jotunn Forge-Masters. [Gigantic Jotunn]"}, {"type": "kill", "target": "CRYSTAL_TYRANT", "count": 1, "description": "Defeat a Crystal Tyrant guarding the master forge."}]'::jsonb, '{"exp": 7200, "currency": 3600, "crd": 1800, "rep": 2400, "items": [{"item_id": "titan_core", "quantity": 2}], "reputation": 50}'::jsonb, false, false, 'fq_conc_076', false, NULL, NULL, NULL, 'quest_concordium.json', 74)
