values ('fq_conc_076', 'Materia War', 'hunt', 'S', 'CONCORDIUM', 'PRIMA_MATERIA_FORGE', 'The Prima Materia War has begun. (Location: Prima Materia Forge, Officer Valen) Rival factions, void entities, and ancient guardians clash for control. Concordium must dominate.', '{"npc_id": "npc_concordium_officer", "name": "", "location": "PRIMA_MATERIA_FORGE"}'::jsonb, '{"min_level": 75, "reputation_required": 4440, "required_quests": ["fq_conc_075"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_VOID_CHANNELER", "count": 6, "description": "Defeat hostile forces in the Forge contested zones. [Aethel Void Channeler]"}, {"type": "kill", "target": "AETHEL_ABYSSAL_REAVER", "count": 6, "description": "Destroy Abyssal forces attempting Forge control. [Aethel Abyssal Reaver]"}, {"type": "collect", "target": "raw_aethel_fragment", "count": 2, "description": "Collect raw aethel fragment (x2). [Item: Raw Aethel Fragment]"}]'::jsonb, '{"exp": 7500, "currency": 3800, "crd": 1900, "rep": 2500, "items": [{"item_id": "power_regulator_core", "quantity": 2}], "reputation": 50}'::jsonb, false, false, 'fq_conc_077', false, NULL, NULL, NULL, 'quest_concordium.json', 75)
