values ('fq_conc_077', 'Titan Forge', 'boss', 'S', 'CONCORDIUM', 'PRIMA_MATERIA_FORGE', 'Residual Gravity Titan energy has spawned Titan Forge Automatons. (Location: Prima Materia Forge, Officer Valen) These machines are immune to conventional damage. Find their thermal weak points.', '{"npc_id": "npc_concordium_officer", "name": "", "location": "PRIMA_MATERIA_FORGE"}'::jsonb, '{"min_level": 76, "reputation_required": 4500, "required_quests": ["fq_conc_076"]}'::jsonb, '[{"type": "kill", "target": "TITAN_FORGE_AUTOMATON", "count": 2, "description": "Defeat Titan Forge Automatons."}, {"type": "collect", "target": "core_fragment", "count": 1, "description": "Collect core fragment (x1). [Item: Core Fragment]"}]'::jsonb, '{"exp": 8000, "currency": 4000, "crd": 2000, "rep": 2600, "items": [{"item_id": "processor_cooling_unit", "quantity": 1}], "reputation": 50}'::jsonb, false, false, 'fq_conc_078', false, NULL, NULL, NULL, 'quest_concordium.json', 76)
