values ('fq_conc_078', 'Proto-Core Assault', 'boss', 'S', 'CONCORDIUM', 'PRIMA_MATERIA_FORGE', 'A Titan Proto Core — a failed Titan gestation — has been reactivated by the Forge''s energy. (Location: Prima Materia Forge, Officer Valen) Destroy it before it matures.', '{"npc_id": "npc_concordium_officer", "name": "", "location": "PRIMA_MATERIA_FORGE"}'::jsonb, '{"min_level": 77, "reputation_required": 4560, "required_quests": ["fq_conc_077"]}'::jsonb, '[{"type": "kill", "target": "TITAN_PROTO_CORE", "count": 1, "description": "Destroy the Titan Proto Core."}, {"type": "kill", "target": "TITAN_FORGE_AUTOMATON", "count": 3, "description": "Defeat Automatons guarding the Proto Core. [Titan Forge Automaton]"}]'::jsonb, '{"exp": 9000, "currency": 4500, "crd": 2250, "rep": 2800, "items": [{"item_id": "titan_core", "quantity": 2}, {"item_id": "gravity_well_core", "quantity": 1}], "reputation": 50}'::jsonb, false, false, 'fq_conc_079', false, NULL, NULL, NULL, 'quest_concordium.json', 77)
