values ('fq_conc_079', 'Sovereign Claim', 'story', 'S', 'CONCORDIUM', 'PRIMA_MATERIA_FORGE', 'With the Forge secured, Concordium''s position is unassailable. (Location: Prima Materia Forge, Officer Valen) But one final test remains. Prove that you are worthy of the title: Legend of Concordium.', '{"npc_id": "npc_concordium_officer", "name": "", "location": "PRIMA_MATERIA_FORGE"}'::jsonb, '{"min_level": 78, "reputation_required": 280, "required_quests": ["fq_conc_078"]}'::jsonb, '[{"type": "kill", "target": "GRAVITY_TITAN", "count": 1, "description": "Face the Gravity Titan one final time."}, {"type": "kill", "target": "ABYSS_HARBINGER", "count": 1, "description": "Confront the Abyss Harbinger once more."}]'::jsonb, '{"exp": 12000, "currency": 6000, "crd": 3000, "rep": 4000, "items": [{"item_id": "drake_heart", "quantity": 1}, {"item_id": "titan_core", "quantity": 2}, {"item_id": "void_core", "quantity": 3}], "reputation": 50}'::jsonb, false, false, 'fq_conc_080', false, NULL, NULL, NULL, 'quest_concordium.json', 78)
