values ('fq_conc_080', 'Legend of Concordium', 'story', 'S', 'CONCORDIUM', 'ORBITAL_SENTINEL_COMMAND', 'You have defeated both Titan and Harbinger in a single campaign. Concordium High Command recognizes your ascension. Return to Orbital Sentinel Command for the highest commendation. Quest giver: Officer Valen at Nexus Core Command Post.', '{"npc_id": "npc_concordium_officer", "name": "", "location": "ORBITAL_SENTINEL_COMMAND"}'::jsonb, '{"min_level": 79, "reputation_required": 330, "required_quests": ["fq_conc_079"]}'::jsonb, '[{"type": "travel", "target": "ORBITAL_SENTINEL_COMMAND", "count": 1, "description": "Return to Orbital Sentinel Command."}, {"type": "collect", "target": "monster_material", "count": 1, "description": "Collect monster material (x1). [Item: Monster Material]"}]'::jsonb, '{"exp": 10000, "currency": 5000, "crd": 2500, "rep": 3500, "items": [{"item_id": "con_elite_recovery_pack", "quantity": 10}, {"item_id": "astral_phase_crystal_pure", "quantity": 3}], "reputation": 50}'::jsonb, false, false, 'fq_conc_081', false, NULL, NULL, NULL, 'quest_concordium.json', 79)
