values ('fq_conc_081', 'Apex Eternal', 'story', 'S', 'CONCORDIUM', 'HIDDEN_AETHELGARDIAN_CITY', 'Ancient records speak of the Hidden Aethelgardian City — a mythical location containing the secrets of the Precursors. Find it and claim its knowledge for Concordium. Quest giver: Officer Valen at Nexus Core Command Post.', '{"npc_id": "npc_concordium_officer", "name": "", "location": "HIDDEN_AETHELGARDIAN_CITY"}'::jsonb, '{"min_level": 80, "reputation_required": 380, "required_quests": ["fq_conc_080"]}'::jsonb, '[{"type": "travel", "target": "HIDDEN_AETHELGARDIAN_CITY", "count": 1, "description": "Discover the Hidden Aethelgardian City."}, {"type": "collect", "target": "void_channeler_core", "count": 3, "description": "Collect void channeler core (x3). [Item: Void Channeler Core]"}]'::jsonb, '{"exp": 8000, "currency": 4000, "crd": 2000, "rep": 2500, "items": [{"item_id": "aethel_core_shard", "quantity": 5}], "reputation": 50}'::jsonb, false, false, 'fq_conc_082', false, NULL, NULL, NULL, 'quest_concordium.json', 80)
