values ('fq_conc_082', 'City Guardians', 'hunt', 'S', 'CONCORDIUM', 'HIDDEN_AETHELGARDIAN_CITY', 'The Aethelgardian City is protected by ancient energy constructs. (Location: Hidden Aethelgardian City, Officer Valen) They recognize no faction — only threats to the Precursor legacy.', '{"npc_id": "npc_concordium_officer", "name": "", "location": "HIDDEN_AETHELGARDIAN_CITY"}'::jsonb, '{"min_level": 81, "reputation_required": 4800, "required_quests": ["fq_conc_081"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_RIFT_STALKER", "count": 8, "description": "Defeat ancient city guardian constructs. [Aethel Rift Stalker]"}, {"type": "kill", "target": "CRYSTAL_TYRANT", "count": 1, "description": "Defeat a Crystal Tyrant gatekeeper."}]'::jsonb, '{"exp": 8500, "currency": 4200, "crd": 2100, "rep": 2700, "items": [{"item_id": "quantum_distortion_stone", "quantity": 2}], "reputation": 50}'::jsonb, false, false, 'fq_conc_083', false, NULL, NULL, NULL, 'quest_concordium.json', 81)
