values ('fq_conc_083', 'Precursor Secrets', 'collect', 'S', 'CONCORDIUM', 'HIDDEN_AETHELGARDIAN_CITY', 'The Precursor Archives reveal the existence of the World Engine — a planetary control system beneath the Siphon Core. (Location: Hidden Aethelgardian City, Officer Valen) Gather more intelligence.', '{"npc_id": "npc_concordium_officer", "name": "", "location": "HIDDEN_AETHELGARDIAN_CITY"}'::jsonb, '{"min_level": 82, "reputation_required": 4860, "required_quests": ["fq_conc_082"]}'::jsonb, '[{"type": "collect", "target": "abyssal_reaver_claw", "count": 4, "description": "Collect abyssal reaver claw (x4). [Item: Abyssal Reaver Claw]"}, {"type": "kill", "target": "AETHEL_ABYSSAL_REAVER", "count": 4, "description": "Defeat Reavers drawn to the Precursor energy. [Aethel Abyssal Reaver]"}]'::jsonb, '{"exp": 8800, "currency": 4400, "crd": 2200, "rep": 2800, "items": [{"item_id": "cognitive_relay_node", "quantity": 3}], "reputation": 50}'::jsonb, false, false, 'fq_conc_084', false, NULL, NULL, NULL, 'quest_concordium.json', 82)
