values ('fq_conc_084', 'Eternal Drake', 'boss', 'S', 'CONCORDIUM', 'SHATTERED_HEART', 'The Ashen Drake has absorbed residual Titan energy and evolved to its maximum threat level. (Location: Shattered Heart, Officer Valen) This is the ultimate draconic challenge.', '{"npc_id": "npc_concordium_officer", "name": "", "location": "SHATTERED_HEART"}'::jsonb, '{"min_level": 83, "reputation_required": 4920, "required_quests": ["fq_conc_083"]}'::jsonb, '[{"type": "kill", "target": "ASHEN_DRAKE", "count": 1, "description": "Defeat the Apex Ashen Drake."}, {"type": "kill", "target": "DRAKE_MINION", "count": 8, "description": "Clear the elite Drake Minion swarm."}]'::jsonb, '{"exp": 12000, "currency": 6000, "crd": 3000, "rep": 4000, "items": [{"item_id": "drake_heart", "quantity": 3}, {"item_id": "ancient_scale", "quantity": 3}], "reputation": 50}'::jsonb, false, false, 'fq_conc_085', false, NULL, NULL, NULL, 'quest_concordium.json', 83)
