values ('fq_conc_085', 'Eternal Harbinger', 'boss', 'S', 'CONCORDIUM', 'VOID_ECHO_CHASM', 'The Abyss Harbinger has been reborn in the deepest chasm, empowered by the chaos of the Titan War. (Location: Void Echo Chasm, Officer Valen) Destroy it permanently.', '{"npc_id": "npc_concordium_officer", "name": "", "location": "VOID_ECHO_CHASM"}'::jsonb, '{"min_level": 84, "reputation_required": 4980, "required_quests": ["fq_conc_084"]}'::jsonb, '[{"type": "kill", "target": "ABYSS_HARBINGER", "count": 1, "description": "Defeat the Eternal Abyss Harbinger."}, {"type": "kill", "target": "SOUL_FRAGMENTER", "count": 2, "description": "Destroy Soul Fragmenters empowering the Harbinger."}]'::jsonb, '{"exp": 13000, "currency": 6500, "crd": 3250, "rep": 4200, "items": [{"item_id": "void_core", "quantity": 5}, {"item_id": "event_horizon_fragment_l", "quantity": 3}], "reputation": 50}'::jsonb, false, false, 'fq_conc_086', false, NULL, NULL, NULL, 'quest_concordium.json', 84)
