values ('fq_conc_086', 'Titan Eternal', 'boss', 'S', 'CONCORDIUM', 'CRADLE_EXPANSE', 'The Gravity Titan has reformed from the planet''s core energy. (Location: Cradle Expanse, Officer Valen) This third manifestation is the most powerful yet. End the cycle.', '{"npc_id": "npc_concordium_officer", "name": "", "location": "CRADLE_EXPANSE"}'::jsonb, '{"min_level": 85, "reputation_required": 5040, "required_quests": ["fq_conc_085"]}'::jsonb, '[{"type": "kill", "target": "GRAVITY_TITAN", "count": 1, "description": "Defeat the Eternal Gravity Titan."}, {"type": "kill", "target": "TITAN_PROTO_CORE", "count": 1, "description": "Destroy the Titan Proto Core fueling its rebirth."}]'::jsonb, '{"exp": 14000, "currency": 7000, "crd": 3500, "rep": 4500, "items": [{"item_id": "titan_core", "quantity": 4}, {"item_id": "gravity_well_core", "quantity": 3}], "reputation": 50}'::jsonb, false, false, 'fq_conc_087', false, NULL, NULL, NULL, 'quest_concordium.json', 85)
