values ('fq_conc_087', 'Tri-Threat Protocol', 'boss', 'S', 'CONCORDIUM', 'PRIMA_MATERIA_FORGE', 'All three Apex entities — Drake, Titan, and Harbinger — have been sighted simultaneously. (Location: Prima Materia Forge, Officer Valen) Concordium authorizes the Tri-Threat Protocol.', '{"npc_id": "npc_concordium_officer", "name": "", "location": "PRIMA_MATERIA_FORGE"}'::jsonb, '{"min_level": 86, "reputation_required": 5100, "required_quests": ["fq_conc_086"]}'::jsonb, '[{"type": "kill", "target": "ASHEN_DRAKE", "count": 1, "description": "Hunt the Drake manifestation. [Ashen Drake]"}, {"type": "kill", "target": "GRAVITY_TITAN", "count": 1, "description": "Confront the Titan manifestation. [Gravity Titan]"}, {"type": "kill", "target": "ABYSS_HARBINGER", "count": 1, "description": "Destroy the Harbinger manifestation. [Abyss Harbinger]"}]'::jsonb, '{"exp": 20000, "currency": 10000, "crd": 5000, "rep": 6000, "items": [{"item_id": "drake_heart", "quantity": 2}, {"item_id": "titan_core", "quantity": 2}, {"item_id": "void_core", "quantity": 3}], "reputation": 50}'::jsonb, false, false, 'fq_conc_088', false, NULL, NULL, NULL, 'quest_concordium.json', 86)
