values ('fq_conc_088', 'Sovereign Control', 'exploration', 'S', 'CONCORDIUM', 'AETHEL_SIPHON_CORE', 'With the Apex entities suppressed, Concordium begins securing absolute sovereignty over Xylos''s planetary infrastructure. (Region: Aethel Siphon Core) Quest giver: Officer Valen at Nexus Core Command Post.', '{"npc_id": "npc_concordium_officer", "name": "", "location": "AETHEL_SIPHON_CORE"}'::jsonb, '{"min_level": 87, "reputation_required": 5160, "required_quests": ["fq_conc_087"]}'::jsonb, '[{"type": "travel", "target": "AETHEL_SIPHON_CORE", "count": 1, "description": "Return to the stabilized Siphon Core. (Travel to: Aethel Siphon Core, Shattered Heart)"}, {"type": "collect", "target": "raw_aethel_fragment", "count": 5, "description": "Collect raw aethel fragment (x5). [Item: Raw Aethel Fragment]"}]'::jsonb, '{"exp": 10000, "currency": 5000, "crd": 2500, "rep": 3200, "items": [{"item_id": "power_regulator_core", "quantity": 3}], "reputation": 50}'::jsonb, false, false, 'fq_conc_089', false, NULL, NULL, NULL, 'quest_concordium.json', 87)
