values ('fq_conc_089', 'World Engine', 'story', 'S', 'CONCORDIUM', 'AETHEL_SIPHON_CORE', 'Beneath the Siphon Core lies the World Engine — the Precursor device that can reshape Xylos. (Location: Aethel Siphon Core, Officer Valen) Concordium must claim it before any other faction discovers it.', '{"npc_id": "npc_concordium_officer", "name": "", "location": "AETHEL_SIPHON_CORE"}'::jsonb, '{"min_level": 88, "reputation_required": 430, "required_quests": ["fq_conc_088"]}'::jsonb, '[{"type": "collect", "target": "monster_material", "count": 3, "description": "Collect monster material (x3). [Item: Monster Material]"}, {"type": "kill", "target": "GIGANTIC_JOTUNN", "count": 2, "description": "Defeat Jotunns guarding the World Engine vault. [Gigantic Jotunn]"}]'::jsonb, '{"exp": 11000, "currency": 5500, "crd": 2750, "rep": 3500, "items": [{"item_id": "aethel_core_shard", "quantity": 5}], "reputation": 50}'::jsonb, false, false, 'fq_conc_090', false, NULL, NULL, NULL, 'quest_concordium.json', 88)
