values ('fq_conc_090', 'Engine Activation', 'story', 'S', 'CONCORDIUM', 'AETHEL_SIPHON_CORE', 'The World Engine is online. (Location: Aethel Siphon Core, Officer Valen) Its power is beyond comprehension. Concordium must use it to bring permanent stability to Xylos. Protect the activation sequence.', '{"npc_id": "npc_concordium_officer", "name": "", "location": "AETHEL_SIPHON_CORE"}'::jsonb, '{"min_level": 89, "reputation_required": 480, "required_quests": ["fq_conc_089"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_ABYSSAL_REAVER", "count": 10, "description": "Defend the World Engine from Abyssal assault. [Aethel Abyssal Reaver]"}, {"type": "kill", "target": "CRYSTAL_TYRANT", "count": 2, "description": "Defeat Tyrants attempting to disrupt the activation. [Crystal Tyrant]"}, {"type": "collect", "target": "raw_aethel_fragment", "count": 1, "description": "Collect raw aethel fragment (x1). [Item: Raw Aethel Fragment]"}]'::jsonb, '{"exp": 13000, "currency": 6500, "crd": 3250, "rep": 4200, "items": [{"item_id": "resonanted_astral_phase_crystal", "quantity": 1}], "reputation": 50}'::jsonb, false, false, 'fq_conc_091', false, NULL, NULL, NULL, 'quest_concordium.json', 89)
