values ('fq_conc_091', 'The Jotunn Purge', 'hunt', 'S', 'CONCORDIUM', 'SEVERANCE_FAULTLINE', 'With the World Engine stabilizing Xylos, remaining hostile entities are being flushed to the surface. Begin the final purge at the Severance Faultline. Quest giver: Officer Valen at Nexus Core Command Post.', '{"npc_id": "npc_concordium_officer", "name": "", "location": "SEVERANCE_FAULTLINE"}'::jsonb, '{"min_level": 90, "reputation_required": 5340, "required_quests": ["fq_conc_090"]}'::jsonb, '[{"type": "kill", "target": "GIGANTIC_JOTUNN", "count": 5, "description": "Purge Jotunns from the faultline. [Gigantic Jotunn]"}, {"type": "kill", "target": "AETHEL_IRON_CARAPACE", "count": 8, "description": "Eliminate Carapace swarms. [Aethel Iron Carapace]"}]'::jsonb, '{"exp": 10000, "currency": 5000, "crd": 2500, "rep": 3200, "items": [{"item_id": "stabilizer_gyro_unit", "quantity": 3}], "reputation": 50}'::jsonb, false, false, 'fq_conc_092', false, NULL, NULL, NULL, 'quest_concordium.json', 90)
