values ('fq_conc_092', 'Abyssal End', 'hunt', 'S', 'CONCORDIUM', 'VOID_ECHO_CHASM', 'The Abyss is collapsing. Its remaining forces are pouring out in desperation. Seal the Void Echo Chasm forever. Quest giver: Officer Valen at Nexus Core Command Post.', '{"npc_id": "npc_concordium_officer", "name": "", "location": "VOID_ECHO_CHASM"}'::jsonb, '{"min_level": 91, "reputation_required": 5400, "required_quests": ["fq_conc_091"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_ABYSSAL_REAVER", "count": 10, "description": "Exterminate the final Abyssal Reavers. [Aethel Abyssal Reaver]"}, {"type": "kill", "target": "VOID_REAVER", "count": 10, "description": "Annihilate all remaining Void Reavers."}]'::jsonb, '{"exp": 11000, "currency": 5500, "crd": 2750, "rep": 3500, "items": [{"item_id": "void_core", "quantity": 5}], "reputation": 50}'::jsonb, false, false, 'fq_conc_093', false, NULL, NULL, NULL, 'quest_concordium.json', 91)
