values ('fq_conc_093', 'Tyrant''s Last Stand', 'boss', 'S', 'CONCORDIUM', 'SHATTERED_HEART', 'Crystal Tyrants have made their final stand in the Shattered Heart. Break their crystalline empire once and for all. Quest giver: Officer Valen at Nexus Core Command Post.', '{"npc_id": "npc_concordium_officer", "name": "", "location": "SHATTERED_HEART"}'::jsonb, '{"min_level": 92, "reputation_required": 5460, "required_quests": ["fq_conc_092"]}'::jsonb, '[{"type": "kill", "target": "CRYSTAL_TYRANT", "count": 3, "description": "Defeat the last Crystal Tyrants."}, {"type": "kill", "target": "ASHEN_DRAKE", "count": 1, "description": "Slay the Drake guarding their retreat. [Ashen Drake]"}]'::jsonb, '{"exp": 12000, "currency": 6000, "crd": 3000, "rep": 4000, "items": [{"item_id": "quantum_distortion_stone", "quantity": 4}], "reputation": 50}'::jsonb, false, false, 'fq_conc_094', false, NULL, NULL, NULL, 'quest_concordium.json', 92)
