values ('fq_conc_094', 'Forge Purification', 'hunt', 'S', 'CONCORDIUM', 'PRIMA_MATERIA_FORGE', 'The Prima Materia Forge must be completely purified of all void corruption. This is Concordium''s final territorial claim. Quest giver: Officer Valen at Nexus Core Command Post.', '{"npc_id": "npc_concordium_officer", "name": "", "location": "PRIMA_MATERIA_FORGE"}'::jsonb, '{"min_level": 93, "reputation_required": 5520, "required_quests": ["fq_conc_093"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_VOID_CHANNELER", "count": 8, "description": "Silence the last Void Channelers. [Aethel Void Channeler]"}, {"type": "kill", "target": "TITAN_FORGE_AUTOMATON", "count": 3, "description": "Disable rogue Forge Automatons. [Titan Forge Automaton]"}]'::jsonb, '{"exp": 11000, "currency": 5500, "crd": 2750, "rep": 3500, "items": [{"item_id": "raw_aethel_core", "quantity": 5}], "reputation": 50}'::jsonb, false, false, 'fq_conc_095', false, NULL, NULL, NULL, 'quest_concordium.json', 93)
