values ('fq_conc_095', 'Expanse Sovereignty', 'hunt', 'S', 'CONCORDIUM', 'CRADLE_EXPANSE', 'The Cradle Expanse is now officially Concordium sovereign territory. Enforce it with overwhelming force. Quest giver: Officer Valen at Nexus Core Command Post.', '{"npc_id": "npc_concordium_officer", "name": "", "location": "CRADLE_EXPANSE"}'::jsonb, '{"min_level": 94, "reputation_required": 5580, "required_quests": ["fq_conc_094"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_RIFT_STALKER", "count": 10, "description": "Clear all hostiles from the Expanse. [Aethel Rift Stalker]"}, {"type": "kill", "target": "GRAVITY_TITAN", "count": 1, "description": "Destroy any residual Titan manifestations. [Gravity Titan]"}]'::jsonb, '{"exp": 13000, "currency": 6500, "crd": 3250, "rep": 4200, "items": [{"item_id": "gravity_well_core", "quantity": 3}], "reputation": 50}'::jsonb, false, false, 'fq_conc_096', false, NULL, NULL, NULL, 'quest_concordium.json', 94)
