values ('fq_conc_096', 'Eternal Vigil', 'hunt', 'S', 'CONCORDIUM', 'ORBITAL_SENTINEL_COMMAND', 'Concordium now watches over Xylos from orbit. (Location: Orbital Sentinel Command, Officer Valen) Maintain eternal vigilance over the planet you have helped to save and rule.', '{"npc_id": "npc_concordium_officer", "name": "", "location": "ORBITAL_SENTINEL_COMMAND"}'::jsonb, '{"min_level": 95, "reputation_required": 5640, "required_quests": ["fq_conc_095"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_IRON_CARAPACE", "count": 10, "description": "Patrol and clear orbital sectors. [Aethel Iron Carapace]"}, {"type": "kill", "target": "AETHEL_CORRUPTED_BEHEMOTH", "count": 3, "description": "Eliminate any remaining Corrupted Behemoths. [Aethel Corrupted Behemoth]"}]'::jsonb, '{"exp": 12000, "currency": 6000, "crd": 3000, "rep": 3800, "items": [{"item_id": "con_elite_recovery_pack", "quantity": 10}], "reputation": 50}'::jsonb, false, false, 'fq_conc_097', false, NULL, NULL, NULL, 'quest_concordium.json', 95)
