values ('fq_conc_097', 'The Final Seal', 'story', 'S', 'CONCORDIUM', 'AETHEL_SIPHON_CORE', 'The World Engine requires one final calibration. (Location: Aethel Siphon Core, Officer Valen) Channel your accumulated power into the Engine to permanently seal the void and stabilize Xylos.', '{"npc_id": "npc_concordium_officer", "name": "", "location": "AETHEL_SIPHON_CORE"}'::jsonb, '{"min_level": 96, "reputation_required": 530, "required_quests": ["fq_conc_096"]}'::jsonb, '[{"type": "kill", "target": "GIGANTIC_JOTUNN", "count": 3, "description": "Defeat Jotunns resisting the final seal. [Gigantic Jotunn]"}, {"type": "kill", "target": "ABYSS_HARBINGER", "count": 1, "description": "Destroy the Harbinger''s final echo. [Abyss Harbinger]"}, {"type": "collect", "target": "monster_material", "count": 3, "description": "Collect monster material (x3). [Item: Monster Material]"}]'::jsonb, '{"exp": 15000, "currency": 7500, "crd": 3750, "rep": 5000, "items": [{"item_id": "resonanted_astral_phase_crystal", "quantity": 2}], "reputation": 50}'::jsonb, false, false, 'fq_conc_098', false, NULL, NULL, NULL, 'quest_concordium.json', 96)
