values ('fq_conc_098', 'One Step from Eternity', 'story', 'S', 'CONCORDIUM', 'PRIMA_MATERIA_FORGE', 'Only one step remains before absolute transcendence. (Location: Prima Materia Forge, Officer Valen) Face the three Apex entities — Jotunn, Drake, and Harbinger — to earn the Eternity Seal.', '{"npc_id": "npc_concordium_officer", "name": "", "location": "PRIMA_MATERIA_FORGE"}'::jsonb, '{"min_level": 97, "reputation_required": 580, "required_quests": ["fq_conc_097"]}'::jsonb, '[{"type": "kill", "target": "GIGANTIC_JOTUNN", "count": 1, "description": "Defeat the Apex Jotunn. [Gigantic Jotunn]"}, {"type": "kill", "target": "ASHEN_DRAKE", "count": 1, "description": "Defeat the Apex Drake. [Ashen Drake]"}, {"type": "kill", "target": "ABYSS_HARBINGER", "count": 1, "description": "Defeat the Apex Harbinger. [Abyss Harbinger]"}, {"type": "collect", "target": "drake_heart", "count": 1, "description": "Collect drake heart (x1). [Item: Drake Heart]"}]'::jsonb, '{"exp": 20000, "currency": 10000, "crd": 5000, "rep": 7000, "items": [{"item_id": "drake_heart", "quantity": 3}, {"item_id": "titan_core", "quantity": 3}, {"item_id": "void_core", "quantity": 5}], "reputation": 50}'::jsonb, false, false, 'fq_conc_099', false, NULL, NULL, NULL, 'quest_concordium.json', 97)
