values ('fq_conc_099', 'The Eternal Crown', 'story', 'S', 'CONCORDIUM', 'VOID_ECHO_CHASM', 'The deepest level of Void Echo Chasm holds the Eternal Crown — the symbol of absolute mastery over Xylos. Descend one final time and claim it. Quest giver: Officer Valen at Nexus Core Command Post.', '{"npc_id": "npc_concordium_officer", "name": "", "location": "VOID_ECHO_CHASM"}'::jsonb, '{"min_level": 98, "reputation_required": 630, "required_quests": ["fq_conc_098"]}'::jsonb, '[{"type": "travel", "target": "VOID_ECHO_CHASM", "count": 1, "description": "Descend to the deepest chasm level. (Travel to: Void Echo Chasm)"}, {"type": "kill", "target": "GRAVITY_TITAN", "count": 1, "description": "Defeat the eternal form of Gravity Titan."}, {"type": "kill", "target": "ABYSS_HARBINGER", "count": 1, "description": "Destroy the eternal form of Abyss Harbinger."}, {"type": "collect", "target": "abyss_fragment", "count": 1, "description": "Collect abyss fragment (x1). [Item: Abyss Fragment]"}]'::jsonb, '{"exp": 25000, "currency": 12000, "crd": 6000, "rep": 8000, "items": [{"item_id": "resonanted_astral_phase_crystal", "quantity": 3}], "reputation": 50}'::jsonb, false, false, 'fq_conc_100', false, NULL, NULL, NULL, 'quest_concordium.json', 98)
