values ('fq_conc_100', 'Eternity', 'story', 'SS', 'CONCORDIUM', 'NEXUS_CORE', 'You have done the impossible. You have claimed the Eternal Crown. Return to Nexus Core where all of Concordium awaits. You are no longer an operative. You are the ETERNAL LEGEND OF CONCORDIUM. Progress through Unity. Strength through Harmony. Now and forever. Quest giver: Officer Valen at Nexus Core Command Post.', '{"npc_id": "npc_concordium_officer", "name": "", "location": "NEXUS_CORE"}'::jsonb, '{"min_level": 99, "reputation_required": 680, "required_quests": ["fq_conc_099"]}'::jsonb, '[{"type": "travel", "target": "NEXUS_CORE", "count": 1, "description": "Return to Nexus Core as the Eternal Legend."}, {"type": "interact", "target": "npc_concordium_officer", "count": 1, "description": "Receive the highest honors from Concordium High Command. (Officer Valen at Nexus Core Command Post)"}]'::jsonb, '{"exp": 50000, "currency": 25000, "crd": 0, "rep": 10000, "items": [{"item_id": "resonanted_astral_phase_crystal", "quantity": 5}, {"item_id": "eternal_crown", "quantity": 1}], "reputation": 5}'::jsonb, false, false, NULL, false, NULL, NULL, NULL, 'quest_concordium.json', 99)
