insert into public.quests (id, title, type, rank, faction, region, description, quest_giver, requirements, objectives, rewards, repeatable, daily, quest_chain_next, popup, popup_trigger, popup_level, popup_prerequisite, source_file, sort_order)
values ('fq_iron_001', 'Welcome to the Machine', 'story', 'D', 'IRON_HEGEMONY', 'SCRAP_FIELD', 'The Iron Hegemony does not recruit — it conscripts, shapes, and deploys. Warlord Harkon Steele built the Hegemony from the Concordium''s security division after the Great Schism, because he understood something the diplomats didn''t: Prima Materia cannot be negotiated with. It can only be controlled by force. The Scrap Field is your proving ground — Broken Scout Drones are jamming logistics, and in the Hegemony, a soldier who can''t clear the field is not a soldier at all. Quest giver: Commander Drax at Bastion Core Command Bunker.', '{"npc_id": "npc_hegemony_commander", "name": "Warlord Harkon Steele", "location": "SCRAP_FIELD"}'::jsonb, '{"min_level": 1, "reputation_required": 0, "required_quests": []}'::jsonb, '[{"type": "kill", "target": "BROKEN_DRONE", "count": 5, "desc": "Destroy Broken Scout Drones.", "description": "Defeat Broken Scout Drone (x5)."}, {"type": "collect", "target": "scrap_metal", "count": 2, "desc": "Collect salvage parts for the war machine.", "description": "Collect scrap metal (x2). [Item: Scrap Metal]"}]'::jsonb, '{"exp": 50, "currency": 30, "crd": 0, "rep": 30, "items": [{"item_id": "con_small_hp_cell", "quantity": 3}, {"item_id": "scrap_metal", "quantity": 2}], "reputation": 5}'::jsonb, false, false, 'fq_iron_002', false, NULL, NULL, NULL, 'quest_iron.json', 0)
on conflict (id) do update set title = excluded.title, type = excluded.type, rank = excluded.rank, faction = excluded.faction, region = excluded.region, description = excluded.description, quest_giver = excluded.quest_giver, requirements = excluded.requirements, objectives = excluded.objectives, rewards = excluded.rewards, repeatable = excluded.repeatable, daily = excluded.daily, quest_chain_next = excluded.quest_chain_next, popup = excluded.popup, popup_trigger = excluded.popup_trigger, popup_level = excluded.popup_level, popup_prerequisite = excluded.popup_prerequisite, source_file = excluded.source_file, sort_order = excluded.sort_order;
insert into public.quests (id, title, type, rank, faction, region, description, quest_giver, requirements, objectives, rewards, repeatable, daily, quest_chain_next, popup, popup_trigger, popup_level, popup_prerequisite, source_file, sort_order)
values ('fq_iron_002', 'No Weakness in the Supply Line', 'story', 'D', 'IRON_HEGEMONY', 'SCRAP_FIELD', 'Scrap Rats have been gnawing through the supply crates the Hegemony uses to move components between the Scrap Field and Bastion Core. In any other organization, this would be a maintenance problem. In the Iron Hegemony, it is a tactical failure — every gap in the supply line is a gap in the war machine''s armor. Warlord Steele has a saying: ''The rat that eats your rations today is the enemy that kills your unit tomorrow.'' Exterminate them. Quest giver: Commander Drax at Bastion Core Command Bunker.', '{"npc_id": "npc_hegemony_commander", "name": "Warlord Harkon Steele", "location": "SCRAP_FIELD"}'::jsonb, '{"min_level": 1, "reputation_required": 5, "required_quests": ["fq_iron_001"]}'::jsonb, '[{"type": "kill", "target": "SCRAP_RAT", "count": 6, "desc": "Exterminate Scrap Rats.", "description": "Defeat Scrap Rat (x6)."}, {"type": "collect", "target": "metal_shard", "count": 3, "desc": "Collect Rat tails for bounty proof.", "description": "Collect metal shard (x3). [Item: Metal Shard]"}]'::jsonb, '{"exp": 55, "currency": 35, "crd": 0, "rep": 35, "items": [{"item_id": "con_small_mp_cell", "quantity": 2}], "reputation": 5}'::jsonb, false, false, 'fq_iron_003', false, NULL, NULL, NULL, 'quest_iron.json', 1)
