insert into public.quests (id, title, type, rank, faction, region, description, quest_giver, requirements, objectives, rewards, repeatable, daily, quest_chain_next, popup, popup_trigger, popup_level, popup_prerequisite, source_file, sort_order)
values ('fq_iron_003', 'The Forge Must Be Fed', 'story', 'D', 'IRON_HEGEMONY', 'SCRAP_FIELD', 'Tink — the Hegemony''s salvage engineer, a person who hasn''t slept a full night in six years because the Bastion forges never sleep either — needs Scrap Drone components to keep the war machine running. (Location: Scrap Field, Tink) The Hegemony''s strength is not just in soldiers; it is in the relentless industrial capacity that turns scrap into weapons. Every drone you disable is another batch of components that becomes a new piece of armor, a new weapon, another tool of control.', '{"npc_id": "npc_salvage_expert", "name": "Warlord Harkon Steele", "location": "SCRAP_FIELD"}'::jsonb, '{"min_level": 2, "reputation_required": 10, "required_quests": ["fq_iron_002"]}'::jsonb, '[{"type": "kill", "target": "SCRAP_DRONE", "count": 5, "desc": "Disable Scrap Drones.", "description": "Defeat Scrap Drone (x5)."}, {"type": "collect", "target": "scrap_metal", "count": 3, "desc": "Salvage drone components.", "description": "Collect scrap metal (x3). [Item: Scrap Metal]"}]'::jsonb, '{"exp": 70, "currency": 40, "crd": 0, "rep": 40, "items": [{"item_id": "scrap_circuit", "quantity": 2}], "reputation": 5}'::jsonb, false, false, 'fq_iron_004', false, NULL, NULL, NULL, 'quest_iron.json', 2)
on conflict (id) do update set title = excluded.title, type = excluded.type, rank = excluded.rank, faction = excluded.faction, region = excluded.region, description = excluded.description, quest_giver = excluded.quest_giver, requirements = excluded.requirements, objectives = excluded.objectives, rewards = excluded.rewards, repeatable = excluded.repeatable, daily = excluded.daily, quest_chain_next = excluded.quest_chain_next, popup = excluded.popup, popup_trigger = excluded.popup_trigger, popup_level = excluded.popup_level, popup_prerequisite = excluded.popup_prerequisite, source_file = excluded.source_file, sort_order = excluded.sort_order;
insert into public.quests (id, title, type, rank, faction, region, description, quest_giver, requirements, objectives, rewards, repeatable, daily, quest_chain_next, popup, popup_trigger, popup_level, popup_prerequisite, source_file, sort_order)
values ('fq_iron_004', 'Iron Does Not Rust', 'story', 'D', 'IRON_HEGEMONY', 'SCRAP_FIELD', 'Rust Mites have colonized the Hegemony''s equipment depot at the Scrap Field perimeter — eating through iron plating that Bastion engineers spent weeks fabricating. In the Hegemony''s ideology, corrosion is not just a material problem; it is a symbol of the weakness that allowed the Great Schism to happen. Warlord Steele demands that the Scrap Field be maintained in fighting condition at all times. A soldier who lets their equipment rot is a soldier who does not believe in the mission. Quest giver: Commander Drax at Bastion Core Command Bunker.', '{"npc_id": "npc_hegemony_commander", "name": "Warlord Harkon Steele", "location": "SCRAP_FIELD"}'::jsonb, '{"min_level": 3, "reputation_required": 15, "required_quests": ["fq_iron_003"]}'::jsonb, '[{"type": "kill", "target": "RUST_MITE", "count": 5, "desc": "Purge Rust Mites.", "description": "Defeat Rust Mite (x5)."}, {"type": "kill", "target": "SCRAP_CRAWLER", "count": 3, "desc": "Clear Scrap Crawlers nesting nearby.", "description": "Defeat Scrap Crawler (x3)."}]'::jsonb, '{"exp": 80, "currency": 50, "crd": 0, "rep": 50, "items": [{"item_id": "rust_chitin", "quantity": 2}], "reputation": 5}'::jsonb, false, false, 'fq_iron_005', false, NULL, NULL, NULL, 'quest_iron.json', 3)
on conflict (id) do update set title = excluded.title, type = excluded.type, rank = excluded.rank, faction = excluded.faction, region = excluded.region, description = excluded.description, quest_giver = excluded.quest_giver, requirements = excluded.requirements, objectives = excluded.objectives, rewards = excluded.rewards, repeatable = excluded.repeatable, daily = excluded.daily, quest_chain_next = excluded.quest_chain_next, popup = excluded.popup, popup_trigger = excluded.popup_trigger, popup_level = excluded.popup_level, popup_prerequisite = excluded.popup_prerequisite, source_file = excluded.source_file, sort_order = excluded.sort_order;
insert into public.quests (id, title, type, rank, faction, region, description, quest_giver, requirements, objectives, rewards, repeatable, daily, quest_chain_next, popup, popup_trigger, popup_level, popup_prerequisite, source_file, sort_order)
values ('fq_iron_005', 'Forged in Bastion Steel', 'tutorial', 'D', 'IRON_HEGEMONY', 'BASTION_CORE', 'Warlord Harkon Steele reviews every conscript personally — or so the rumor goes. What is true is that a summons to Bastion Core means someone has noticed you are more than standard material. The Hegemony does not believe in generalist soldiers; every weapon has a function, and a soldier who has not found theirs is a weapon without an edge. At Bastion Core''s war hall, you will choose the form your lethality takes. Choose it correctly. There are no second specializations. Quest giver: War Marshal Drax at Bastion Core War College.', '{"npc_id": "npc_hegemony_class_trainer", "name": "War Marshal Drax", "location": "BASTION_CORE"}'::jsonb, '{"min_level": 4, "reputation_required": 20, "required_quests": ["fq_iron_004"], "required_items": ["recomendation_letters"]}'::jsonb, '[{"type": "interact", "target": "npc_hegemony_class_trainer", "count": 1, "desc": "Report to War Marshal Drax at the Bastion.", "description": "Speak with npc hegemony class trainer. (War Marshal Drax at Bastion Core War College)"}, {"type": "interact", "target": "class_change_screen", "count": 1, "desc": "Select your combat specialization.", "description": "Speak with class change screen."}, {"type": "kill", "target": "BROKEN_DRONE", "count": 3, "desc": "Demonstrate your worth against Scrap Hounds.", "description": "Defeat Broken Scout Drone (x3)."}]'::jsonb, '{"exp": 400, "currency": 200, "crd": 0, "rep": 150, "items": [{"item_id": "wpn_iron_sword", "quantity": 1}, {"item_id": "arm_iron_plate", "quantity": 1}, {"item_id": "rare_emblem", "quantity": 1}, {"item_id": "echo_memory_core_low", "quantity": 1}], "reputation": 5}'::jsonb, false, false, 'fq_iron_006', true, 'on_quest_complete', 4, 'fq_iron_004', 'quest_iron.json', 4)
on conflict (id) do update set title = excluded.title, type = excluded.type, rank = excluded.rank, faction = excluded.faction, region = excluded.region, description = excluded.description, quest_giver = excluded.quest_giver, requirements = excluded.requirements, objectives = excluded.objectives, rewards = excluded.rewards, repeatable = excluded.repeatable, daily = excluded.daily, quest_chain_next = excluded.quest_chain_next, popup = excluded.popup, popup_trigger = excluded.popup_trigger, popup_level = excluded.popup_level, popup_prerequisite = excluded.popup_prerequisite, source_file = excluded.source_file, sort_order = excluded.sort_order;
insert into public.quests (id, title, type, rank, faction, region, description, quest_giver, requirements, objectives, rewards, repeatable, daily, quest_chain_next, popup, popup_trigger, popup_level, popup_prerequisite, source_file, sort_order)
values ('fq_iron_006', 'The Ravine Is Ours Now', 'story', 'D', 'IRON_HEGEMONY', 'IRON_RAVINE', 'The Iron Ravine sits on mineral deposits that could supply the Bastion''s forges for a generation — deposits the Concordium surveyed and filed away while debating policy, and that the Meridian Cartel is already sending surveyors to assess. Warlord Steele does not debate. He sends soldiers. The Iron Hegemony''s doctrine is simple: the one who controls the mineral controls the war machine, and the one who controls the war machine controls everything else. Establish the forward base. Quest giver: Commander Drax at Bastion Core Command Bunker.', '{"npc_id": "npc_hegemony_commander", "name": "Warlord Harkon Steele", "location": "IRON_RAVINE"}'::jsonb, '{"min_level": 5, "reputation_required": 20, "required_quests": ["fq_iron_005"]}'::jsonb, '[{"type": "travel", "target": "IRON_RAVINE", "count": 1, "desc": "Enter the Iron Ravine.", "description": "Travel to IRON RAVINE. (Travel to: Iron Ravine)"}, {"type": "collect", "target": "rat_hide", "count": 1, "desc": "Deploy a forward base beacon.", "description": "Collect rat hide (x1). [Item: Rat Hide]"}]'::jsonb, '{"exp": 100, "currency": 60, "crd": 0, "rep": 60, "items": [{"item_id": "mat_iron_ore", "quantity": 3}], "reputation": 5}'::jsonb, false, false, 'fq_iron_007', false, NULL, NULL, NULL, 'quest_iron.json', 5)
on conflict (id) do update set title = excluded.title, type = excluded.type, rank = excluded.rank, faction = excluded.faction, region = excluded.region, description = excluded.description, quest_giver = excluded.quest_giver, requirements = excluded.requirements, objectives = excluded.objectives, rewards = excluded.rewards, repeatable = excluded.repeatable, daily = excluded.daily, quest_chain_next = excluded.quest_chain_next, popup = excluded.popup, popup_trigger = excluded.popup_trigger, popup_level = excluded.popup_level, popup_prerequisite = excluded.popup_prerequisite, source_file = excluded.source_file, sort_order = excluded.sort_order;
insert into public.quests (id, title, type, rank, faction, region, description, quest_giver, requirements, objectives, rewards, repeatable, daily, quest_chain_next, popup, popup_trigger, popup_level, popup_prerequisite, source_file, sort_order)
values ('fq_iron_007', 'Competing Claims Are Not Claims', 'story', 'D', 'IRON_HEGEMONY', 'IRON_RAVINE', 'Iron Ravine Miners — independent operators who have worked these veins for years, who have no Hegemony contracts and no Hegemony protection — are blocking access to the central mineral shaft. In the Concordium, this would be a dispute. In the Meridian Cartel, this would be a negotiation. In the Iron Hegemony, Warlord Steele has a single word for independent operators who stand between his soldiers and a strategic resource: obstacles. Quest giver: Gorn at Iron Ravine Mine Entrance.', '{"npc_id": "npc_iron_miner", "name": "Warlord Harkon Steele", "location": "IRON_RAVINE"}'::jsonb, '{"min_level": 6, "reputation_required": 25, "required_quests": ["fq_iron_006"]}'::jsonb, '[{"type": "kill", "target": "IRON_RAVINE_MINER", "count": 5, "desc": "Defeat Iron Ravine Miners.", "description": "Defeat Iron Ravine Miner (x5)."}, {"type": "collect", "target": "refined_scrap", "count": 3, "desc": "Collect Ravine Ore for the forges.", "description": "Collect refined scrap (x3). [Item: Refined Scrap]"}]'::jsonb, '{"exp": 120, "currency": 70, "crd": 0, "rep": 70, "items": [{"item_id": "mat_iron_ore", "quantity": 5}], "reputation": 5}'::jsonb, false, false, 'fq_iron_008', false, NULL, NULL, NULL, 'quest_iron.json', 6)
