values ('fq_iron_009', 'There Is Only One Authority Here', 'story', 'D', 'IRON_HEGEMONY', 'IRON_RAVINE', 'A Scrapfield Enforcer — a rogue combat machine that predates the Hegemony''s own war-mech program — has been claiming the central ravine as its patrol zone and attacking Hegemony survey teams on sight. Its combat protocols may actually be superior to some Hegemony-built machines, which Tink finds professionally embarrassing and Warlord Steele finds unacceptable. The Iron Hegemony is the only authority in the Iron Ravine. Enforce that fact. Quest giver: Commander Drax at Bastion Core Command Bunker.', '{"npc_id": "npc_hegemony_commander", "name": "Warlord Harkon Steele", "location": "IRON_RAVINE"}'::jsonb, '{"min_level": 8, "reputation_required": 35, "required_quests": ["fq_iron_008"]}'::jsonb, '[{"type": "kill", "target": "SCRAPFIELD_ENFORCER", "count": 1, "desc": "Defeat the Scrapfield Enforcer.", "description": "Defeat Scrapfield Enforcer (x1)."}, {"type": "kill", "target": "IRON_RAVINE_SENTINEL", "count": 1, "desc": "Destroy a Ravine Sentinel guarding the Enforcer.", "description": "Defeat Iron Ravine Sentinel (x1)."}]'::jsonb, '{"exp": 250, "currency": 150, "crd": 0, "rep": 150, "items": [{"item_id": "scrap_circuit", "quantity": 3}], "reputation": 5}'::jsonb, false, false, 'fq_iron_010', false, NULL, NULL, NULL, 'quest_iron.json', 8)
