insert into public.quests (id, title, type, rank, faction, region, description, quest_giver, requirements, objectives, rewards, repeatable, daily, quest_chain_next, popup, popup_trigger, popup_level, popup_prerequisite, source_file, sort_order)
values ('fq_iron_010', 'Strip Them to the Core', 'story', 'D', 'IRON_HEGEMONY', 'IRON_RAVINE', 'Ravine Scrap Golems are what happens when the Severance''s corrupted energy animates salvaged machinery without anyone controlling the result — walking fortresses of mismatched metal and raw aethel charge that will attack anything within range. (Location: Iron Ravine, Commander Drax) Warlord Steele does not waste time theorizing about what they are. He looks at them and sees two things: a threat to neutralize, and a salvage yield that Tink has already calculated down to the last circuit. Break them. Take what the Hegemony needs.', '{"npc_id": "npc_hegemony_commander", "name": "Warlord Harkon Steele", "location": "IRON_RAVINE"}'::jsonb, '{"min_level": 9, "reputation_required": 40, "required_quests": ["fq_iron_009"]}'::jsonb, '[{"type": "kill", "target": "RAVINE_SCRAP_GOLEM", "count": 2, "desc": "Destroy Ravine Scrap Golems.", "description": "Defeat Ravine Scrap Golem (x2)."}, {"type": "collect", "target": "scrap_core", "count": 1, "desc": "Salvage Golem core components.", "description": "Collect scrap core (x1). [Item: Scrap Core]"}]'::jsonb, '{"exp": 300, "currency": 180, "crd": 0, "rep": 180, "items": [{"item_id": "core_fragment", "quantity": 2}], "reputation": 5}'::jsonb, false, false, 'fq_iron_011', false, NULL, NULL, NULL, 'quest_iron.json', 9)
