insert into public.quests (id, title, type, rank, faction, region, description, quest_giver, requirements, objectives, rewards, repeatable, daily, quest_chain_next, popup, popup_trigger, popup_level, popup_prerequisite, source_file, sort_order)
values ('fq_iron_011', 'What Wars Leave Behind', 'story', 'C', 'IRON_HEGEMONY', 'WAR_MACHINE_GRAVEYARD', 'The War Machine Graveyard is a cemetery of titans — pre-Severance war constructs that fought wars whose names have been forgotten, left to rust in a field that no other faction wants to enter. Warlord Steele walks it differently. He sees it as a library, every destroyed machine a lesson about what failed and why. The Iron Hegemony''s doctrine forbids forgetting the last war. Enter the Graveyard. See what losing looks like, so you understand what winning requires. Quest giver: Commander Drax at Bastion Core Command Bunker.', '{"npc_id": "npc_hegemony_commander", "name": "Warlord Harkon Steele", "location": "WAR_MACHINE_GRAVEYARD"}'::jsonb, '{"min_level": 10, "reputation_required": 45, "required_quests": ["fq_iron_010"]}'::jsonb, '[{"type": "travel", "target": "WAR_MACHINE_GRAVEYARD", "count": 1, "desc": "Enter the War Machine Graveyard.", "description": "Travel to WAR MACHINE GRAVEYARD. (Travel to: War Machine Graveyard)"}, {"type": "collect", "target": "refined_scrap", "count": 2, "desc": "Gather battlefield intelligence.", "description": "Collect refined scrap (x2). [Item: Refined Scrap]"}]'::jsonb, '{"exp": 280, "currency": 150, "crd": 0, "rep": 150, "items": [{"item_id": "con_minor_stim_pack", "quantity": 2}], "reputation": 5}'::jsonb, false, false, 'fq_iron_012', false, NULL, NULL, NULL, 'quest_iron.json', 10)
