values ('fq_iron_012', 'The Graveyard Has One Owner', 'story', 'C', 'IRON_HEGEMONY', 'WAR_MACHINE_GRAVEYARD', 'War Machine Wreckers — scavengers who strip the Graveyard''s titan remains for parts to sell to the Meridian Cartel and OmniCorp — have been operating here for years without Hegemony authorization. (Location: War Machine Graveyard, Foreman Brigg) Foreman Brigg''s inventory assessments show they''ve already taken components that the Hegemony''s Titan Assembly Yard needed. The Graveyard''s lessons belong to the Iron Hegemony. Its parts belong to the Iron Hegemony. Its scavengers belong on the ground.', '{"npc_id": "npc_assembly_foreman", "name": "Warlord Harkon Steele", "location": "WAR_MACHINE_GRAVEYARD"}'::jsonb, '{"min_level": 11, "reputation_required": 50, "required_quests": ["fq_iron_011"]}'::jsonb, '[{"type": "kill", "target": "WAR_MACHINE_WRECKER", "count": 5, "desc": "Destroy War Machine Wreckers.", "description": "Defeat War Machine Wrecker (x5)."}, {"type": "collect", "target": "refined_scrap", "count": 3, "desc": "Collect usable parts from destroyed Wreckers.", "description": "Collect refined scrap (x3). [Item: Refined Scrap]"}]'::jsonb, '{"exp": 320, "currency": 170, "crd": 0, "rep": 170, "items": [{"item_id": "scrap_metal", "quantity": 4}], "reputation": 5}'::jsonb, false, false, 'fq_iron_013', false, NULL, NULL, NULL, 'quest_iron.json', 11)
