insert into public.quests (id, title, type, rank, faction, region, description, quest_giver, requirements, objectives, rewards, repeatable, daily, quest_chain_next, popup, popup_trigger, popup_level, popup_prerequisite, source_file, sort_order)
values ('fq_iron_013', 'Tink''s Inventory List', 'story', 'C', 'IRON_HEGEMONY', 'WAR_MACHINE_GRAVEYARD', 'Tink — whose actual feelings about the War Machine Graveyard are somewhere between reverence and obsession — has produced a precise inventory of components the Hegemony needs and the War Machine Scavengers are taking. The Scavengers are not random looters; they are organized, they have buyers, and their operation is directly funded by OmniCorp. Every scrap core they remove is a weapon the Hegemony does not build. Tink says ''please.'' Warlord Steele says ''eliminate them.''', '{"npc_id": "npc_salvage_expert", "name": "Warlord Harkon Steele", "location": "WAR_MACHINE_GRAVEYARD"}'::jsonb, '{"min_level": 12, "reputation_required": 55, "required_quests": ["fq_iron_012"]}'::jsonb, '[{"type": "kill", "target": "WAR_MACHINE_SCAVENGER", "count": 5, "desc": "Eliminate War Machine Scavengers.", "description": "Defeat War Machine Scavenger (x5)."}, {"type": "collect", "target": "scrap_core", "count": 3, "desc": "Recover salvaged technology.", "description": "Collect scrap core (x3). [Item: Scrap Core]"}]'::jsonb, '{"exp": 360, "currency": 190, "crd": 0, "rep": 200, "items": [{"item_id": "rusted_cybernetic_arm", "quantity": 1}], "reputation": 5}'::jsonb, false, false, 'fq_iron_014', false, NULL, NULL, NULL, 'quest_iron.json', 12)
