insert into public.quests (id, title, type, rank, faction, region, description, quest_giver, requirements, objectives, rewards, repeatable, daily, quest_chain_next, popup, popup_trigger, popup_level, popup_prerequisite, source_file, sort_order)
values ('fq_iron_014', 'Reverse-Engineer the Past', 'story', 'C', 'IRON_HEGEMONY', 'WAR_MACHINE_GRAVEYARD', 'War Machine Sentinels — automated guardian constructs still running on battle-programming written before the Severance — continue patrolling the Graveyard as if the war they were built for is still ongoing. (Location: War Machine Graveyard, Foreman Brigg) Tink has analyzed their combat protocols and found techniques the Hegemony''s current Titan Assembly Yard has not re-discovered. Disable them carefully. Every Sentinel destroyed is a lesson extracted from the past to make the Hegemony''s future war machines more lethal.', '{"npc_id": "npc_assembly_foreman", "name": "Warlord Harkon Steele", "location": "WAR_MACHINE_GRAVEYARD"}'::jsonb, '{"min_level": 13, "reputation_required": 60, "required_quests": ["fq_iron_013"]}'::jsonb, '[{"type": "kill", "target": "WAR_MACHINE_SENTINEL", "count": 3, "desc": "Disable War Machine Sentinels.", "description": "Defeat War Machine Sentinel (x3)."}, {"type": "collect", "target": "sensor_chip", "count": 1, "desc": "Extract combat protocol data.", "description": "Collect sensor chip (x1). [Item: Sensor Chip]"}]'::jsonb, '{"exp": 450, "currency": 240, "crd": 0, "rep": 240, "items": [{"item_id": "damaged_servo_motor", "quantity": 2}], "reputation": 5}'::jsonb, false, false, 'fq_iron_015', false, NULL, NULL, NULL, 'quest_iron.json', 13)
