insert into public.quests (id, title, type, rank, faction, region, description, quest_giver, requirements, objectives, rewards, repeatable, daily, quest_chain_next, popup, popup_trigger, popup_level, popup_prerequisite, source_file, sort_order)
values ('fq_iron_015', 'Full Tactical Suppression', 'story', 'C', 'IRON_HEGEMONY', 'WAR_MACHINE_GRAVEYARD', 'Warlord Steele does not believe in partial victories. A contested zone is a weak zone — every Wrecker and Scavenger still active in the Graveyard represents a hole in the Hegemony''s tactical control. The full sweep order is simple and absolute: everything in the Graveyard that is not Iron Hegemony is either neutralized or tagged for disposal. By the end of this operation, the War Machine Graveyard will be an Iron Hegemony asset with no asterisks. Quest giver: Commander Drax at Bastion Core Command Bunker.', '{"npc_id": "npc_hegemony_commander", "name": "Warlord Harkon Steele", "location": "WAR_MACHINE_GRAVEYARD"}'::jsonb, '{"min_level": 14, "reputation_required": 65, "required_quests": ["fq_iron_014"]}'::jsonb, '[{"type": "kill", "target": "WAR_MACHINE_WRECKER", "count": 4, "desc": "Sweep remaining Wreckers.", "description": "Defeat War Machine Wrecker (x4)."}, {"type": "kill", "target": "WAR_MACHINE_SCAVENGER", "count": 4, "desc": "Sweep remaining Scavengers.", "description": "Defeat War Machine Scavenger (x4)."}]'::jsonb, '{"exp": 500, "currency": 280, "crd": 0, "rep": 300, "items": [{"item_id": "scrap_circuit", "quantity": 3}], "reputation": 5}'::jsonb, false, false, 'fq_iron_016', false, NULL, NULL, NULL, 'quest_iron.json', 14)
