insert into public.quests (id, title, type, rank, faction, region, description, quest_giver, requirements, objectives, rewards, repeatable, daily, quest_chain_next, popup, popup_trigger, popup_level, popup_prerequisite, source_file, sort_order)
values ('fq_iron_016', 'Target Practice', 'story', 'C', 'IRON_HEGEMONY', 'WAR_MACHINE_GRAVEYARD', 'Multiple War Machine Sentinels are converging on the Hegemony''s salvage teams — an automated counter-response to the Hegemony''s presence in their patrol zones. (Location: War Machine Graveyard, Commander Drax) Warlord Steele''s briefing is characteristically brief: ''Multiple Sentinels converging. This is not a threat. This is target practice.'' The Hegemony''s soldiers are not told to be careful. They are told to be efficient. Efficiency is the highest virtue in the Iron Hegemony''s doctrine of war.', '{"npc_id": "npc_hegemony_commander", "name": "Warlord Harkon Steele", "location": "WAR_MACHINE_GRAVEYARD"}'::jsonb, '{"min_level": 15, "reputation_required": 70, "required_quests": ["fq_iron_015"]}'::jsonb, '[{"type": "kill", "target": "WAR_MACHINE_SENTINEL", "count": 4, "desc": "Destroy converging Sentinels.", "description": "Defeat War Machine Sentinel (x4)."}, {"type": "collect", "target": "scrap_core", "count": 1, "desc": "File the Sentinel wreckage report.", "description": "Collect scrap core (x1). [Item: Scrap Core]"}]'::jsonb, '{"exp": 520, "currency": 290, "crd": 0, "rep": 310, "items": [{"item_id": "processor_cooling_unit", "quantity": 1}], "reputation": 5}'::jsonb, false, false, 'fq_iron_017', false, NULL, NULL, NULL, 'quest_iron.json', 15)
