insert into public.quests (id, title, type, rank, faction, region, description, quest_giver, requirements, objectives, rewards, repeatable, daily, quest_chain_next, popup, popup_trigger, popup_level, popup_prerequisite, source_file, sort_order)
values ('fq_iron_017', 'The Bastion Needs Feeding', 'story', 'C', 'IRON_HEGEMONY', 'WAR_MACHINE_GRAVEYARD', 'Foreman Brigg has a requisition list from the Bastion''s Titan Assembly program — specific components from specific models in the Graveyard that cannot be manufactured any other way. (Location: War Machine Graveyard, Foreman Brigg) The program is behind schedule. Three rival factions are ahead of the Hegemony in their own advanced weapons programs, and Warlord Steele does not tolerate being behind. The Graveyard Wreckers are in the retrieval zones again. Remove them. Retrieve what the Bastion needs. Bring the Hegemony back ahead.', '{"npc_id": "npc_assembly_foreman", "name": "Warlord Harkon Steele", "location": "WAR_MACHINE_GRAVEYARD"}'::jsonb, '{"min_level": 16, "reputation_required": 75, "required_quests": ["fq_iron_016"]}'::jsonb, '[{"type": "collect", "target": "refined_scrap", "count": 4, "desc": "Retrieve specified components.", "description": "Collect refined scrap (x4). [Item: Refined Scrap]"}, {"type": "kill", "target": "WAR_MACHINE_WRECKER", "count": 3, "desc": "Clear the retrieval zone.", "description": "Defeat War Machine Wrecker (x3)."}]'::jsonb, '{"exp": 480, "currency": 260, "crd": 0, "rep": 260, "items": [{"item_id": "neural_interface_socket", "quantity": 1}], "reputation": 5}'::jsonb, false, false, 'fq_iron_018', false, NULL, NULL, NULL, 'quest_iron.json', 16)
