insert into public.quests (id, title, type, rank, faction, region, description, quest_giver, requirements, objectives, rewards, repeatable, daily, quest_chain_next, popup, popup_trigger, popup_level, popup_prerequisite, source_file, sort_order)
values ('fq_iron_018', 'The Graveyard Has a Commander', 'story', 'C', 'IRON_HEGEMONY', 'WAR_MACHINE_GRAVEYARD', 'Deep in the War Machine Graveyard''s protected core zone, a Sentinel Commander — a war construct with hierarchical battle protocols that can coordinate the scattered Sentinels into a unified tactical force — has activated. Tink believes it has been dormant for centuries, triggered by the Hegemony''s salvage operations. Warlord Steele believes this is irrelevant. The Graveyard belongs to the Iron Hegemony. Destroy the Commander. Plant the claim beacon. End this. Quest giver: Commander Drax at Bastion Core Command Bunker.', '{"npc_id": "npc_hegemony_commander", "name": "Warlord Harkon Steele", "location": "WAR_MACHINE_GRAVEYARD"}'::jsonb, '{"min_level": 17, "reputation_required": 80, "required_quests": ["fq_iron_017"]}'::jsonb, '[{"type": "kill", "target": "WAR_MACHINE_SENTINEL", "count": 5, "desc": "Destroy the Sentinel Commander and its unit.", "description": "Defeat War Machine Sentinel (x5)."}, {"type": "collect", "target": "scrap_core", "count": 1, "desc": "Plant the Hegemony claim beacon.", "description": "Collect scrap core (x1). [Item: Scrap Core]"}]'::jsonb, '{"exp": 600, "currency": 330, "crd": 0, "rep": 350, "items": [{"item_id": "tactical_sensor_cluster", "quantity": 1}], "reputation": 5}'::jsonb, false, false, 'fq_iron_019', false, NULL, NULL, NULL, 'quest_iron.json', 17)
