values ('fq_iron_019', 'No Anomalies in Our Territory', 'story', 'C', 'IRON_HEGEMONY', 'WAR_MACHINE_GRAVEYARD', 'A Resonance Echo — the kind of energy entity the Arcanum Seekers would write excited papers about — has formed in the Graveyard''s deep sector, drawn by the resonance from the now-active Sentinel Commander. (Location: War Machine Graveyard, Commander Drax) It is disrupting every piece of Hegemony electronic equipment within range and coordinating erratic behavior in the surviving Sentinels. The Iron Hegemony does not tolerate anomalies in controlled territory. This is controlled territory now. Destroy it.', '{"npc_id": "npc_hegemony_commander", "name": "Warlord Harkon Steele", "location": "WAR_MACHINE_GRAVEYARD"}'::jsonb, '{"min_level": 18, "reputation_required": 85, "required_quests": ["fq_iron_018"]}'::jsonb, '[{"type": "kill", "target": "RESONANCE_ECHO", "count": 1, "desc": "Defeat the Resonance Echo.", "description": "Defeat Resonance Echo (x1)."}, {"type": "kill", "target": "WAR_MACHINE_SENTINEL", "count": 2, "desc": "Clear Sentinel escorts.", "description": "Defeat War Machine Sentinel (x2)."}]'::jsonb, '{"exp": 800, "currency": 450, "crd": 0, "rep": 450, "items": [{"item_id": "entropy_core", "quantity": 1}], "reputation": 5}'::jsonb, false, false, 'fq_iron_020', false, NULL, NULL, NULL, 'quest_iron.json', 18)
