values ('fq_iron_020', 'The Bastion Recognizes You', 'story', 'C', 'IRON_HEGEMONY', 'BASTION_CORE', 'The War Machine Graveyard is secured. The Titan Assembly program has its components. Warlord Harkon Steele does not give compliments — he gives promotions, which mean exactly the same thing in the Iron Hegemony. Return to Bastion Core for your Advanced Combat elevation. The Titan Assembly Yard awaits, and what is built there will change the balance of power on Xylos. You are going to help build it. Quest giver: Commander Drax at Bastion Core Command Bunker.', '{"npc_id": "npc_hegemony_commander", "name": "Warlord Harkon Steele", "location": "BASTION_CORE"}'::jsonb, '{"min_level": 19, "reputation_required": 90, "required_quests": ["fq_iron_019"]}'::jsonb, '[{"type": "travel", "target": "BASTION_CORE", "count": 1, "desc": "Return to the Bastion.", "description": "Travel to BASTION CORE. (Travel to: Bastion Core)"}, {"type": "collect", "target": "core_fragment", "count": 1, "desc": "Receive the Advanced Combat Badge.", "description": "Collect core fragment (x1). [Item: Core Fragment]"}]'::jsonb, '{"exp": 900, "currency": 500, "crd": 0, "rep": 500, "items": [{"item_id": "con_medium_hp_cell", "quantity": 5}], "reputation": 5}'::jsonb, false, false, 'fq_iron_021', false, NULL, NULL, NULL, 'quest_iron.json', 19)
