values ('fq_iron_021', 'Iron Incursion', 'exploration', 'B', 'IRON_HEGEMONY', 'TITAN_ASSEMBLY_YARD', 'The Titan Assembly Yard was once where Precursor war machines were born. The Hegemony will make it our primary production facility. Quest giver: Foreman Brigg at Titan Assembly Yard Command Post.', '{"npc_id": "npc_assembly_foreman", "name": "Foreman Brigg", "location": "TITAN_ASSEMBLY_YARD"}'::jsonb, '{"min_level": 20, "reputation_required": 1140, "required_quests": ["fq_iron_020"]}'::jsonb, '[{"type": "travel", "target": "TITAN_ASSEMBLY_YARD", "count": 1, "desc": "Enter the Titan Assembly Yard.", "description": "Travel to TITAN ASSEMBLY YARD. (Travel to: Titan Assembly Yard)"}, {"type": "collect", "target": "core_fragment", "count": 2, "desc": "Recover Assembly schematics.", "description": "Collect core fragment (x2). [Item: Core Fragment]"}]'::jsonb, '{"exp": 600, "currency": 350, "crd": 105, "rep": 350, "items": [{"item_id": "con_nutrient_ration", "quantity": 3}], "reputation": 10}'::jsonb, false, false, 'fq_iron_022', false, NULL, NULL, NULL, 'quest_iron.json', 20)
