values ('fq_iron_022', 'Drone Sweep', 'hunt', 'B', 'IRON_HEGEMONY', 'TITAN_ASSEMBLY_YARD', 'Titan Assembly Drones still function on ancient protocols. (Location: Titan Assembly Yard, Foreman Brigg) Override their programming with force.', '{"npc_id": "npc_assembly_foreman", "name": "Foreman Brigg", "location": "TITAN_ASSEMBLY_YARD"}'::jsonb, '{"min_level": 21, "reputation_required": 1200, "required_quests": ["fq_iron_021"]}'::jsonb, '[{"type": "kill", "target": "TITAN_ASSEMBLY_DRONE", "count": 6, "desc": "Destroy Titan Assembly Drones.", "description": "Defeat Titan Assembly Drone (x6)."}, {"type": "collect", "target": "circuit_fragment", "count": 2, "desc": "Extract override codes.", "description": "Collect circuit fragment (x2). [Item: Circuit Fragment]"}]'::jsonb, '{"exp": 650, "currency": 380, "crd": 114, "rep": 380, "items": [{"item_id": "scrap_circuit", "quantity": 3}], "reputation": 10}'::jsonb, false, false, 'fq_iron_023', false, NULL, NULL, NULL, 'quest_iron.json', 21)
