values ('fq_iron_023', 'Sentinel Outpost', 'boss', 'B', 'IRON_HEGEMONY', 'TITAN_ASSEMBLY_YARD', 'Titan Assembly Sentinels guard the central assembly line. (Location: Titan Assembly Yard, Commander Drax) Breach their defenses and claim the line for Hegemony production.', '{"npc_id": "npc_hegemony_commander", "name": "Commander Drax", "location": "TITAN_ASSEMBLY_YARD"}'::jsonb, '{"min_level": 22, "reputation_required": 1260, "required_quests": ["fq_iron_022"]}'::jsonb, '[{"type": "kill", "target": "TITAN_ASSEMBLY_SENTINEL", "count": 3, "desc": "Destroy Titan Assembly Sentinels.", "description": "Defeat Titan Assembly Sentinel (x3)."}, {"type": "collect", "target": "scrap_core", "count": 1, "desc": "Seize the assembly line control terminal.", "description": "Collect scrap core (x1). [Item: Scrap Core]"}]'::jsonb, '{"exp": 750, "currency": 420, "crd": 126, "rep": 450, "items": [{"item_id": "damaged_servo_motor", "quantity": 2}], "reputation": 10}'::jsonb, false, false, 'fq_iron_024', false, NULL, NULL, NULL, 'quest_iron.json', 22)
