values ('fq_iron_024', 'Forge Automaton', 'boss', 'B', 'IRON_HEGEMONY', 'TITAN_ASSEMBLY_YARD', 'Titan Forge Automatons are apex construction machines. (Location: Titan Assembly Yard, Foreman Brigg) Disable them and study their assembly protocols.', '{"npc_id": "npc_assembly_foreman", "name": "Foreman Brigg", "location": "TITAN_ASSEMBLY_YARD"}'::jsonb, '{"min_level": 23, "reputation_required": 1320, "required_quests": ["fq_iron_023"]}'::jsonb, '[{"type": "kill", "target": "TITAN_FORGE_AUTOMATON", "count": 2, "desc": "Disable Titan Forge Automatons.", "description": "Defeat Titan Forge Automaton (x2)."}, {"type": "collect", "target": "titan_core", "count": 1, "desc": "Extract Automaton assembly protocols.", "description": "Collect titan core (x1). [Item: Titan Core]"}]'::jsonb, '{"exp": 850, "currency": 460, "crd": 138, "rep": 480, "items": [{"item_id": "hydraulic_piston_fragment", "quantity": 1}], "reputation": 10}'::jsonb, false, false, 'fq_iron_025', false, NULL, NULL, NULL, 'quest_iron.json', 23)
