values ('fq_iron_025', 'Proto Core', 'boss', 'B', 'IRON_HEGEMONY', 'TITAN_ASSEMBLY_YARD', 'A Titan Proto Core — a failed Titan — has reactivated. (Location: Titan Assembly Yard, Commander Drax) This is a live-fire exercise. Destroy it.', '{"npc_id": "npc_hegemony_commander", "name": "Commander Drax", "location": "TITAN_ASSEMBLY_YARD"}'::jsonb, '{"min_level": 24, "reputation_required": 1380, "required_quests": ["fq_iron_024"]}'::jsonb, '[{"type": "kill", "target": "TITAN_PROTO_CORE", "count": 1, "desc": "Destroy the Titan Proto Core.", "description": "Defeat Titan Proto Core (x1)."}, {"type": "collect", "target": "titan_core", "count": 1, "desc": "Collect Proto Core battle data.", "description": "Collect titan core (x1). [Item: Titan Core]"}]'::jsonb, '{"exp": 1000, "currency": 550, "crd": 165, "rep": 550, "items": [{"item_id": "titan_core", "quantity": 1}], "reputation": 10}'::jsonb, false, false, 'fq_iron_026', false, NULL, NULL, NULL, 'quest_iron.json', 24)
