values ('fq_iron_026', 'Skirmish Ring', 'exploration', 'B', 'IRON_HEGEMONY', 'BORDER_SKIRMISH_RING', 'The Border Skirmish Ring is where factions test their strength. The Hegemony does not test — we dominate. Quest giver: Commander Drax at Bastion Core Command Bunker.', '{"npc_id": "npc_hegemony_commander", "name": "Commander Drax", "location": "BORDER_SKIRMISH_RING"}'::jsonb, '{"min_level": 25, "reputation_required": 1440, "required_quests": ["fq_iron_025"]}'::jsonb, '[{"type": "travel", "target": "BORDER_SKIRMISH_RING", "count": 1, "desc": "Enter the Border Skirmish Ring.", "description": "Travel to BORDER SKIRMISH RING. (Travel to: Border Skirmish Ring)"}, {"type": "collect", "target": "contraband_core", "count": 2, "desc": "Gather enemy movement intelligence.", "description": "Collect contraband core (x2). [Item: Contraband Core]"}]'::jsonb, '{"exp": 700, "currency": 400, "crd": 120, "rep": 400, "items": [{"item_id": "con_nutrient_ration", "quantity": 3}], "reputation": 10}'::jsonb, false, false, 'fq_iron_027', false, NULL, NULL, NULL, 'quest_iron.json', 25)
