values ('fq_iron_027', 'Border Patrol', 'hunt', 'B', 'IRON_HEGEMONY', 'BORDER_SKIRMISH_RING', 'Patrol the skirmish ring and eliminate any non-Hegemony forces. (Location: Border Skirmish Ring, Commander Drax) The border is ours.', '{"npc_id": "npc_hegemony_commander", "name": "Commander Drax", "location": "BORDER_SKIRMISH_RING"}'::jsonb, '{"min_level": 26, "reputation_required": 1500, "required_quests": ["fq_iron_026"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_RIFT_STALKER", "count": 6, "desc": "Eliminate rival faction scouts.", "description": "Defeat Aethel Rift Stalker (x6)."}, {"type": "collect", "target": "refined_scrap", "count": 1, "desc": "Complete border patrol and claim the badge.", "description": "Collect refined scrap (x1). [Item: Refined Scrap]"}]'::jsonb, '{"exp": 750, "currency": 430, "crd": 129, "rep": 430, "items": [{"item_id": "scrap_circuit", "quantity": 2}], "reputation": 10}'::jsonb, false, false, 'fq_iron_028', false, NULL, NULL, NULL, 'quest_iron.json', 26)
