values ('fq_iron_028', 'Behemoth Assault', 'boss', 'B', 'IRON_HEGEMONY', 'BORDER_SKIRMISH_RING', 'Aethel Behemoths are being used as living siege weapons by rival factions. (Location: Border Skirmish Ring, Commander Drax) Destroy the weapon before it reaches Hegemony lines.', '{"npc_id": "npc_hegemony_commander", "name": "Commander Drax", "location": "BORDER_SKIRMISH_RING"}'::jsonb, '{"min_level": 27, "reputation_required": 1560, "required_quests": ["fq_iron_027"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_BEHEMOTH", "count": 2, "desc": "Destroy the enemy Behemoth siege units.", "description": "Defeat Aethel Behemoth (x2)."}, {"type": "collect", "target": "raw_aethel_core", "count": 1, "desc": "Document the siege weapon tactics.", "description": "Collect raw aethel core (x1). [Item: Raw Aethel Core]"}]'::jsonb, '{"exp": 900, "currency": 520, "crd": 156, "rep": 520, "items": [{"item_id": "aethel_core_shard", "quantity": 2}], "reputation": 10}'::jsonb, false, false, 'fq_iron_029', false, NULL, NULL, NULL, 'quest_iron.json', 27)
