values ('fq_iron_029', 'Sentinel Assembly', 'boss', 'B', 'IRON_HEGEMONY', 'TITAN_ASSEMBLY_YARD', 'The Assembly Yard has produced new Sentinel variants. (Location: Titan Assembly Yard, Foreman Brigg) Test Hegemony combat doctrine against them.', '{"npc_id": "npc_assembly_foreman", "name": "Foreman Brigg", "location": "TITAN_ASSEMBLY_YARD"}'::jsonb, '{"min_level": 28, "reputation_required": 1620, "required_quests": ["fq_iron_028"]}'::jsonb, '[{"type": "kill", "target": "TITAN_ASSEMBLY_SENTINEL", "count": 4, "desc": "Destroy new Sentinel variants.", "description": "Defeat Titan Assembly Sentinel (x4)."}, {"type": "collect", "target": "scrap_core", "count": 1, "desc": "Document Sentinel variant capabilities.", "description": "Collect scrap core (x1). [Item: Scrap Core]"}]'::jsonb, '{"exp": 850, "currency": 480, "crd": 144, "rep": 480, "items": [{"item_id": "stabilizer_gyro_unit", "quantity": 1}], "reputation": 10}'::jsonb, false, false, 'fq_iron_030', false, NULL, NULL, NULL, 'quest_iron.json', 28)
