values ('fq_iron_030', 'Ascension Test', 'story', 'B', 'IRON_HEGEMONY', 'BASTION_CORE', 'War Marshal Drax has called for your Ascension Test. (Location: Bastion Core, War Marshal Drax) Prove your strength has surpassed the rank of common soldier.', '{"npc_id": "npc_hegemony_class_trainer", "name": "War Marshal Drax", "location": "BASTION_CORE"}'::jsonb, '{"min_level": 29, "reputation_required": 95, "required_quests": ["fq_iron_029"]}'::jsonb, '[{"type": "interact", "target": "npc_hegemony_class_trainer", "count": 1, "desc": "Report to War Marshal Drax.", "description": "Speak with npc hegemony class trainer. (War Marshal Drax at Bastion Core War College)"}, {"type": "kill", "target": "RESONANCE_ECHO", "count": 1, "desc": "Defeat the Resonance Echo as your strength test.", "description": "Defeat Resonance Echo (x1)."}, {"type": "kill", "target": "TITAN_PROTO_CORE", "count": 1, "desc": "Destroy a Titan Proto Core as your endurance test.", "description": "Defeat Titan Proto Core (x1)."}]'::jsonb, '{"exp": 2500, "currency": 1200, "crd": 360, "rep": 800, "items": [{"item_id": "con_elite_recovery_pack", "quantity": 2}, {"item_id": "titan_core", "quantity": 1}], "reputation": 10}'::jsonb, false, false, 'fq_iron_031', true, 'on_quest_complete', 29, 'fq_iron_029', 'quest_iron.json', 29)
