values ('fq_iron_031', 'Skies of Iron', 'exploration', 'A', 'IRON_HEGEMONY', 'ORBITAL_SENTINEL_COMMAND', 'The Hegemony now controls the ground. The next frontier is the sky. Secure the Orbital Sentinel Command. Quest giver: Commander Drax at Bastion Core Command Bunker.', '{"npc_id": "npc_hegemony_commander", "name": "Commander Drax", "location": "ORBITAL_SENTINEL_COMMAND"}'::jsonb, '{"min_level": 30, "reputation_required": 1740, "required_quests": ["fq_iron_030"]}'::jsonb, '[{"type": "travel", "target": "ORBITAL_SENTINEL_COMMAND", "count": 1, "desc": "Report to Orbital Sentinel Command.", "description": "Travel to ORBITAL SENTINEL COMMAND. (Travel to: Orbital Sentinel Command)"}, {"type": "collect", "target": "void_core", "count": 1, "desc": "Deploy the Hegemony orbital control beacon.", "description": "Collect void core (x1). [Item: Void Core]"}]'::jsonb, '{"exp": 900, "currency": 500, "crd": 250, "rep": 500, "items": [{"item_id": "con_elite_recovery_pack", "quantity": 1}], "reputation": 25}'::jsonb, false, false, 'fq_iron_032', false, NULL, NULL, NULL, 'quest_iron.json', 30)
