values ('fq_iron_032', 'Drake Recon', 'hunt', 'A', 'IRON_HEGEMONY', 'CRADLE_EXPANSE', 'The Ashen Drake threatens Hegemony air superiority. (Location: Cradle Expanse, Commander Drax) Conduct reconnaissance and engage if necessary.', '{"npc_id": "npc_hegemony_commander", "name": "Commander Drax", "location": "CRADLE_EXPANSE"}'::jsonb, '{"min_level": 31, "reputation_required": 1800, "required_quests": ["fq_iron_031"]}'::jsonb, '[{"type": "kill", "target": "ASHEN_DRAKE", "count": 1, "desc": "Engage the Ashen Drake for reconnaissance.", "description": "Defeat Ashen Drake (x1)."}, {"type": "collect", "target": "ancient_scale", "count": 2, "desc": "Record Drake combat data.", "description": "Collect ancient scale (x2). [Item: Ancient Scale]"}]'::jsonb, '{"exp": 1200, "currency": 650, "crd": 325, "rep": 650, "items": [{"item_id": "drake_heart", "quantity": 1}], "reputation": 25}'::jsonb, false, false, 'fq_iron_033', false, NULL, NULL, NULL, 'quest_iron.json', 31)
