values ('fq_iron_033', 'Iron Carapace Breach', 'hunt', 'A', 'IRON_HEGEMONY', 'CRADLE_EXPANSE', 'Aethel Iron Carapaces are armored threats. (Location: Cradle Expanse, Commander Drax) Hegemony tanks need live-fire practice. Be the gun.', '{"npc_id": "npc_hegemony_commander", "name": "Commander Drax", "location": "CRADLE_EXPANSE"}'::jsonb, '{"min_level": 32, "reputation_required": 1860, "required_quests": ["fq_iron_032"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_IRON_CARAPACE", "count": 6, "desc": "Destroy Aethel Iron Carapaces.", "description": "Defeat Aethel Iron Carapace (x6)."}, {"type": "collect", "target": "carapace_fragment", "count": 3, "desc": "Harvest armor plates for the forges.", "description": "Collect carapace fragment (x3). [Item: Carapace Fragment]"}]'::jsonb, '{"exp": 1400, "currency": 750, "crd": 375, "rep": 750, "items": [{"item_id": "rusted_plate", "quantity": 3}], "reputation": 25}'::jsonb, false, false, 'fq_iron_034', false, NULL, NULL, NULL, 'quest_iron.json', 32)
