values ('fq_iron_034', 'Behemoth Target', 'boss', 'A', 'IRON_HEGEMONY', 'CRADLE_EXPANSE', 'Aethel Corrupted Behemoths are priority targets. (Location: Cradle Expanse, Commander Drax) Any threat to Hegemony territory receives the same response: elimination.', '{"npc_id": "npc_hegemony_commander", "name": "Commander Drax", "location": "CRADLE_EXPANSE"}'::jsonb, '{"min_level": 33, "reputation_required": 1920, "required_quests": ["fq_iron_033"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_CORRUPTED_BEHEMOTH", "count": 2, "desc": "Eliminate Corrupted Behemoths.", "description": "Defeat Aethel Corrupted Behemoth (x2)."}, {"type": "collect", "target": "crystal_core", "count": 2, "desc": "Confirm target elimination.", "description": "Collect crystal core (x2). [Item: Crystal Core]"}]'::jsonb, '{"exp": 1600, "currency": 850, "crd": 425, "rep": 850, "items": [{"item_id": "aethel_fragment", "quantity": 2}], "reputation": 25}'::jsonb, false, false, 'fq_iron_035', false, NULL, NULL, NULL, 'quest_iron.json', 33)
