values ('fq_iron_035', 'Abyssal Front', 'boss', 'A', 'IRON_HEGEMONY', 'CRADLE_EXPANSE', 'Aethel Abyssal Reavers are the enemy''s shock troops. (Location: Cradle Expanse, Commander Drax) Meet them with Hegemony steel.', '{"npc_id": "npc_hegemony_commander", "name": "Commander Drax", "location": "CRADLE_EXPANSE"}'::jsonb, '{"min_level": 34, "reputation_required": 1980, "required_quests": ["fq_iron_034"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_ABYSSAL_REAVER", "count": 4, "desc": "Destroy Abyssal Reaver shock troops.", "description": "Defeat Aethel Abyssal Reaver (x4)."}, {"type": "collect", "target": "void_channeler_core", "count": 1, "desc": "File the after-action report.", "description": "Collect void channeler core (x1). [Item: Void Channeler Core]"}]'::jsonb, '{"exp": 1800, "currency": 950, "crd": 475, "rep": 950, "items": [{"item_id": "event_horizon_fragment", "quantity": 1}], "reputation": 25}'::jsonb, false, false, 'fq_iron_036', false, NULL, NULL, NULL, 'quest_iron.json', 34)
