values ('fq_iron_036', 'Orbital Defense Grid', 'hunt', 'A', 'IRON_HEGEMONY', 'ORBITAL_SENTINEL_COMMAND', 'Rival factions probe the orbital defense grid. (Location: Orbital Sentinel Command, Commander Drax) Remind them why Hegemony controls the skies.', '{"npc_id": "npc_hegemony_commander", "name": "Commander Drax", "location": "ORBITAL_SENTINEL_COMMAND"}'::jsonb, '{"min_level": 35, "reputation_required": 2040, "required_quests": ["fq_iron_035"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_RIFT_STALKER", "count": 6, "desc": "Repel enemy probes.", "description": "Defeat Aethel Rift Stalker (x6)."}, {"type": "kill", "target": "AETHEL_VOID_CHANNELER", "count": 3, "desc": "Neutralize void threats to the grid.", "description": "Defeat Aethel Void Channeler (x3)."}]'::jsonb, '{"exp": 1500, "currency": 800, "crd": 400, "rep": 800, "items": [{"item_id": "con_elite_recovery_pack", "quantity": 3}], "reputation": 25}'::jsonb, false, false, 'fq_iron_037', false, NULL, NULL, NULL, 'quest_iron.json', 35)
