values ('fq_iron_037', 'Drake Hunt', 'boss', 'A', 'IRON_HEGEMONY', 'CRADLE_EXPANSE', 'The Ashen Drake has been sighted again. (Location: Cradle Expanse, Commander Drax) This time, Hegemony authorizes a kill order. Bring it down.', '{"npc_id": "npc_hegemony_commander", "name": "Commander Drax", "location": "CRADLE_EXPANSE"}'::jsonb, '{"min_level": 36, "reputation_required": 2100, "required_quests": ["fq_iron_036"]}'::jsonb, '[{"type": "kill", "target": "ASHEN_DRAKE", "count": 1, "desc": "Hunt and kill the Ashen Drake.", "description": "Defeat Ashen Drake (x1)."}, {"type": "collect", "target": "ancient_scale", "count": 1, "desc": "Confirm the Drake kill.", "description": "Collect ancient scale (x1). [Item: Ancient Scale]"}]'::jsonb, '{"exp": 2500, "currency": 1300, "crd": 650, "rep": 900, "items": [{"item_id": "drake_heart", "quantity": 2}], "reputation": 25}'::jsonb, false, false, 'fq_iron_038', false, NULL, NULL, NULL, 'quest_iron.json', 36)
