values ('fq_iron_038', 'Ground Assault', 'hunt', 'A', 'IRON_HEGEMONY', 'BORDER_SKIRMISH_RING', 'Full ground assault on enemy positions in the Skirmish Ring. (Location: Border Skirmish Ring, Commander Drax) Hegemony doctrine: overwhelming force.', '{"npc_id": "npc_hegemony_commander", "name": "Commander Drax", "location": "BORDER_SKIRMISH_RING"}'::jsonb, '{"min_level": 37, "reputation_required": 2160, "required_quests": ["fq_iron_037"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_IRON_CARAPACE", "count": 8, "desc": "Assault enemy positions.", "description": "Defeat Aethel Iron Carapace (x8)."}, {"type": "collect", "target": "core_fragment", "count": 2, "desc": "Claim territory with Hegemony beacons.", "description": "Collect core fragment (x2). [Item: Core Fragment]"}]'::jsonb, '{"exp": 1700, "currency": 900, "crd": 450, "rep": 900, "items": [{"item_id": "scrap_metal", "quantity": 5}], "reputation": 25}'::jsonb, false, false, 'fq_iron_039', false, NULL, NULL, NULL, 'quest_iron.json', 37)
