values ('fq_iron_039', 'Abyssal Counter-Offensive', 'boss', 'A', 'IRON_HEGEMONY', 'CRADLE_EXPANSE', 'The Abyss Counter-Offensive has begun. (Location: Cradle Expanse, Commander Drax) Multiple Reaver battalions advance on Hegemony positions. Break their offensive.', '{"npc_id": "npc_hegemony_commander", "name": "Commander Drax", "location": "CRADLE_EXPANSE"}'::jsonb, '{"min_level": 38, "reputation_required": 2220, "required_quests": ["fq_iron_038"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_ABYSSAL_REAVER", "count": 6, "desc": "Break the Abyssal counter-offensive.", "description": "Defeat Aethel Abyssal Reaver (x6)."}, {"type": "kill", "target": "AETHEL_VOID_CHANNELER", "count": 3, "desc": "Kill the Channeler commanders.", "description": "Defeat Aethel Void Channeler (x3)."}]'::jsonb, '{"exp": 2000, "currency": 1100, "crd": 550, "rep": 1100, "items": [{"item_id": "gravity_well_core", "quantity": 1}], "reputation": 25}'::jsonb, false, false, 'fq_iron_040', false, NULL, NULL, NULL, 'quest_iron.json', 38)
