values ('fq_iron_040', 'Master Commander', 'story', 'A', 'IRON_HEGEMONY', 'BASTION_CORE', 'The Master Commander trial. (Location: Bastion Core, Commander Drax) Defeat the Ashen Drake and two elite guardians. Only the strongest lead Hegemony forces into battle.', '{"npc_id": "npc_hegemony_commander", "name": "Commander Drax", "location": "BASTION_CORE"}'::jsonb, '{"min_level": 39, "reputation_required": 105, "required_quests": ["fq_iron_039"]}'::jsonb, '[{"type": "kill", "target": "ASHEN_DRAKE", "count": 1, "desc": "Defeat the Ashen Drake.", "description": "Defeat Ashen Drake (x1)."}, {"type": "kill", "target": "AETHEL_BEHEMOTH", "count": 1, "desc": "Destroy an Aethel Behemoth.", "description": "Defeat Aethel Behemoth (x1)."}, {"type": "kill", "target": "TITAN_PROTO_CORE", "count": 1, "desc": "Destroy a Titan Proto Core.", "description": "Defeat Titan Proto Core (x1)."}]'::jsonb, '{"exp": 5000, "currency": 2500, "crd": 1250, "rep": 2000, "items": [{"item_id": "drake_heart", "quantity": 1}, {"item_id": "titan_core", "quantity": 1}, {"item_id": "con_elite_recovery_pack", "quantity": 5}], "reputation": 25}'::jsonb, false, false, 'fq_iron_041', false, NULL, NULL, NULL, 'quest_iron.json', 39)
