values ('fq_iron_041', 'Subjugating the Chasm', 'exploration', 'S', 'IRON_HEGEMONY', 'VOID_ECHO_CHASM', 'The Void Echo Chasm is the most hostile environment on Xylos. The Hegemony will establish a forward base here. Fear is not an option. Quest giver: Commander Drax at Bastion Core Command Bunker.', '{"npc_id": "npc_hegemony_commander", "name": "Commander Drax", "location": "VOID_ECHO_CHASM"}'::jsonb, '{"min_level": 40, "reputation_required": 2340, "required_quests": ["fq_iron_040"]}'::jsonb, '[{"type": "travel", "target": "VOID_ECHO_CHASM", "count": 1, "desc": "Enter the Void Echo Chasm.", "description": "Travel to VOID ECHO CHASM. (Travel to: Void Echo Chasm)"}, {"type": "collect", "target": "void_channeler_core", "count": 2, "desc": "Conduct chasm terrain survey.", "description": "Collect void channeler core (x2). [Item: Void Channeler Core]"}]'::jsonb, '{"exp": 1800, "currency": 900, "crd": 450, "rep": 600, "items": [{"item_id": "void_fragment", "quantity": 3}], "reputation": 50}'::jsonb, false, false, 'fq_iron_042', false, NULL, NULL, NULL, 'quest_iron.json', 40)
