values ('fq_iron_042', 'Reaver Engagement', 'hunt', 'S', 'IRON_HEGEMONY', 'VOID_ECHO_CHASM', 'Void Reavers are the chasm''s defenders. (Location: Void Echo Chasm, Commander Drax) Engage and destroy. Hegemony fears no darkness.', '{"npc_id": "npc_hegemony_commander", "name": "Commander Drax", "location": "VOID_ECHO_CHASM"}'::jsonb, '{"min_level": 41, "reputation_required": 2400, "required_quests": ["fq_iron_041"]}'::jsonb, '[{"type": "kill", "target": "VOID_REAVER", "count": 6, "desc": "Engage and destroy Void Reavers.", "description": "Defeat Void Reaver (x6)."}, {"type": "collect", "target": "void_fragment", "count": 1, "desc": "Submit kill tally to command.", "description": "Collect void fragment (x1). [Item: Void Fragment]"}]'::jsonb, '{"exp": 1900, "currency": 950, "crd": 475, "rep": 650, "items": [{"item_id": "void_core", "quantity": 1}], "reputation": 50}'::jsonb, false, false, 'fq_iron_043', false, NULL, NULL, NULL, 'quest_iron.json', 41)
