values ('fq_iron_043', 'Channeler Purge', 'story', 'S', 'IRON_HEGEMONY', 'VOID_ECHO_CHASM', 'Void Channelers perform rituals that empower the Abyss. (Location: Void Echo Chasm, Commander Drax) Purge them. The Hegemony leaves no enemy power source intact.', '{"npc_id": "npc_hegemony_commander", "name": "Commander Drax", "location": "VOID_ECHO_CHASM"}'::jsonb, '{"min_level": 42, "reputation_required": 130, "required_quests": ["fq_iron_042"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_VOID_CHANNELER", "count": 6, "desc": "Purge Void Channelers and their rituals.", "description": "Defeat Aethel Void Channeler (x6)."}, {"type": "collect", "target": "raw_aethel_fragment", "count": 1, "desc": "Report ritual disruption status.", "description": "Collect raw aethel fragment (x1). [Item: Raw Aethel Fragment]"}]'::jsonb, '{"exp": 2100, "currency": 1050, "crd": 525, "rep": 700, "items": [{"item_id": "event_horizon_fragment", "quantity": 2}], "reputation": 50}'::jsonb, false, false, 'fq_iron_044', false, NULL, NULL, NULL, 'quest_iron.json', 42)
