values ('fq_iron_044', 'Abyssal Extermination', 'hunt', 'S', 'IRON_HEGEMONY', 'VOID_ECHO_CHASM', 'Abyssal Reavers are the enemy''s elite. (Location: Void Echo Chasm, Commander Drax) Exterminate them. The Hegemony tolerates no elite but its own.', '{"npc_id": "npc_hegemony_commander", "name": "Commander Drax", "location": "VOID_ECHO_CHASM"}'::jsonb, '{"min_level": 43, "reputation_required": 2520, "required_quests": ["fq_iron_043"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_ABYSSAL_REAVER", "count": 6, "desc": "Exterminate Abyssal Reavers.", "description": "Defeat Aethel Abyssal Reaver (x6)."}, {"type": "collect", "target": "void_channeler_core", "count": 1, "desc": "File extermination completion report.", "description": "Collect void channeler core (x1). [Item: Void Channeler Core]"}]'::jsonb, '{"exp": 2200, "currency": 1100, "crd": 550, "rep": 750, "items": [{"item_id": "void_crystal_shard", "quantity": 2}], "reputation": 50}'::jsonb, false, false, 'fq_iron_045', false, NULL, NULL, NULL, 'quest_iron.json', 43)
