values ('fq_iron_045', 'Behemoth Elimination', 'boss', 'S', 'IRON_HEGEMONY', 'VOID_ECHO_CHASM', 'Corrupted Behemoths in the chasm are juiced on void energy. (Location: Void Echo Chasm, Commander Drax) Prove that Hegemony steel cuts deeper than void corruption.', '{"npc_id": "npc_hegemony_commander", "name": "Commander Drax", "location": "VOID_ECHO_CHASM"}'::jsonb, '{"min_level": 44, "reputation_required": 2580, "required_quests": ["fq_iron_044"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_CORRUPTED_BEHEMOTH", "count": 3, "desc": "Eliminate Corrupted Behemoths.", "description": "Defeat Aethel Corrupted Behemoth (x3)."}, {"type": "collect", "target": "crystal_core", "count": 1, "desc": "Collect void-resistance data for armor research.", "description": "Collect crystal core (x1). [Item: Crystal Core]"}]'::jsonb, '{"exp": 2500, "currency": 1300, "crd": 650, "rep": 800, "items": [{"item_id": "corrupted_synapse_cluster", "quantity": 2}], "reputation": 50}'::jsonb, false, false, 'fq_iron_046', false, NULL, NULL, NULL, 'quest_iron.json', 44)
