values ('fq_iron_046', 'Soul Breaker', 'boss', 'S', 'IRON_HEGEMONY', 'VOID_ECHO_CHASM', 'Soul Fragmenters attempt to break the minds of Hegemony soldiers. (Location: Void Echo Chasm, Commander Drax) They will fail. Destroy these psychological warfare units.', '{"npc_id": "npc_hegemony_commander", "name": "Commander Drax", "location": "VOID_ECHO_CHASM"}'::jsonb, '{"min_level": 45, "reputation_required": 2640, "required_quests": ["fq_iron_045"]}'::jsonb, '[{"type": "kill", "target": "SOUL_FRAGMENTER", "count": 2, "desc": "Destroy Soul Fragmenters.", "description": "Defeat Soul Fragmenter (x2)."}, {"type": "collect", "target": "core_fragment", "count": 1, "desc": "Report soldier morale status.", "description": "Collect core fragment (x1). [Item: Core Fragment]"}]'::jsonb, '{"exp": 3000, "currency": 1600, "crd": 800, "rep": 1000, "items": [{"item_id": "brainwave_oscillator", "quantity": 1}], "reputation": 50}'::jsonb, false, false, 'fq_iron_047', false, NULL, NULL, NULL, 'quest_iron.json', 45)
