values ('fq_iron_047', 'Chrono Elimination', 'boss', 'S', 'IRON_HEGEMONY', 'VOID_ECHO_CHASM', 'Chrono Wraiths warp time around Hegemony positions. (Location: Void Echo Chasm, Commander Drax) Counter their temporal attacks with overwhelming firepower.', '{"npc_id": "npc_hegemony_commander", "name": "Commander Drax", "location": "VOID_ECHO_CHASM"}'::jsonb, '{"min_level": 46, "reputation_required": 2700, "required_quests": ["fq_iron_046"]}'::jsonb, '[{"type": "kill", "target": "CHRONO_WRAITH", "count": 2, "desc": "Eliminate Chrono Wraiths.", "description": "Defeat Chrono Wraith (x2)."}, {"type": "collect", "target": "monster_material", "count": 1, "desc": "Develop temporal countermeasure data.", "description": "Collect monster material (x1). [Item: Monster Material]"}]'::jsonb, '{"exp": 3500, "currency": 1800, "crd": 900, "rep": 1100, "items": [{"item_id": "quantum_distortion_stone", "quantity": 1}], "reputation": 50}'::jsonb, false, false, 'fq_iron_048', false, NULL, NULL, NULL, 'quest_iron.json', 46)
