values ('fq_iron_048', 'Jotunn Break', 'boss', 'S', 'IRON_HEGEMONY', 'VOID_ECHO_CHASM', 'A Gigantic Jotunn blocks the advance. (Location: Void Echo Chasm, Commander Drax) Hegemony doctrine: destroy the obstacle and keep moving.', '{"npc_id": "npc_hegemony_commander", "name": "Commander Drax", "location": "VOID_ECHO_CHASM"}'::jsonb, '{"min_level": 47, "reputation_required": 2760, "required_quests": ["fq_iron_047"]}'::jsonb, '[{"type": "kill", "target": "GIGANTIC_JOTUNN", "count": 1, "desc": "Destroy the Gigantic Jotunn.", "description": "Defeat Gigantic Jotunn (x1)."}, {"type": "collect", "target": "core_fragment", "count": 1, "desc": "Deploy advance beacon past the Jotunn.", "description": "Collect core fragment (x1). [Item: Core Fragment]"}]'::jsonb, '{"exp": 3500, "currency": 1800, "crd": 900, "rep": 1000, "items": [{"item_id": "titan_core", "quantity": 1}], "reputation": 50}'::jsonb, false, false, 'fq_iron_049', false, NULL, NULL, NULL, 'quest_iron.json', 47)
