values ('fq_iron_049', 'Heart Breach', 'exploration', 'S', 'IRON_HEGEMONY', 'SHATTERED_HEART', 'The Shattered Heart is the enemy''s core territory. Breach it. The Hegemony attacks — always. Quest giver: Commander Drax at Bastion Core Command Bunker.', '{"npc_id": "npc_hegemony_commander", "name": "Commander Drax", "location": "SHATTERED_HEART"}'::jsonb, '{"min_level": 48, "reputation_required": 2820, "required_quests": ["fq_iron_048"]}'::jsonb, '[{"type": "travel", "target": "SHATTERED_HEART", "count": 1, "desc": "Breach the Shattered Heart.", "description": "Travel to SHATTERED HEART. (Travel to: Shattered Heart, Shattered Heart)"}, {"type": "collect", "target": "void_core", "count": 1, "desc": "Establish the breach head.", "description": "Collect void core (x1). [Item: Void Core]"}]'::jsonb, '{"exp": 2500, "currency": 1300, "crd": 650, "rep": 800, "items": [{"item_id": "con_elite_recovery_pack", "quantity": 2}], "reputation": 50}'::jsonb, false, false, 'fq_iron_050', false, NULL, NULL, NULL, 'quest_iron.json', 48)
