values ('fq_iron_050', 'The Drake''s Fall', 'boss', 'S', 'IRON_HEGEMONY', 'SHATTERED_HEART', 'THE DRAKE EXECUTION. The Ashen Drake rules the Shattered Heart. The Hegemony will execute it. Raid Tier-1: lead the assault and bring down the Drake. Victory through Conquest. Quest giver: Commander Drax at Bastion Core Command Bunker.', '{"npc_id": "npc_hegemony_commander", "name": "Commander Drax", "location": "SHATTERED_HEART"}'::jsonb, '{"min_level": 49, "reputation_required": 2880, "required_quests": ["fq_iron_049"]}'::jsonb, '[{"type": "kill", "target": "ASHEN_DRAKE", "count": 1, "desc": "EXECUTE THE ASHEN DRAKE.", "description": "Defeat Ashen Drake (x1)."}, {"type": "kill", "target": "DRAKE_MINION", "count": 5, "desc": "Clear Drake Minions from the lair.", "description": "Defeat Drake Minion (x5)."}, {"type": "collect", "target": "ancient_scale", "count": 1, "desc": "Claim the Drake''s head as trophy for the Bastion.", "description": "Collect ancient scale (x1). [Item: Ancient Scale]"}]'::jsonb, '{"exp": 8000, "currency": 4000, "crd": 2000, "rep": 2500, "items": [{"item_id": "drake_heart", "quantity": 2}, {"item_id": "ancient_scale", "quantity": 1}, {"item_id": "con_elite_recovery_pack", "quantity": 5}], "reputation": 50}'::jsonb, false, false, 'fq_iron_051', false, NULL, NULL, NULL, 'quest_iron.json', 49)
