values ('fq_iron_051', 'Void Warfare', 'boss', 'S', 'IRON_HEGEMONY', 'VOID_ECHO_CHASM', 'The Soul Fragmenter threat has escalated. (Location: Void Echo Chasm, Commander Drax) Multiple units are deploying. This is now a military campaign.', '{"npc_id": "npc_hegemony_commander", "name": "Commander Drax", "location": "VOID_ECHO_CHASM"}'::jsonb, '{"min_level": 50, "reputation_required": 2940, "required_quests": ["fq_iron_050"]}'::jsonb, '[{"type": "kill", "target": "SOUL_FRAGMENTER", "count": 3, "desc": "Destroy the Fragmenter battalions.", "description": "Defeat Soul Fragmenter (x3)."}, {"type": "collect", "target": "monster_material", "count": 1, "desc": "Submit campaign status to High Command.", "description": "Collect monster material (x1). [Item: Monster Material]"}]'::jsonb, '{"exp": 6000, "currency": 3000, "crd": 1500, "rep": 2000, "items": [{"item_id": "brainwave_reader", "quantity": 1}], "reputation": 50}'::jsonb, false, false, 'fq_iron_052', false, NULL, NULL, NULL, 'quest_iron.json', 50)
