values ('fq_iron_052', 'Total Void Control', 'hunt', 'S', 'IRON_HEGEMONY', 'VOID_ECHO_CHASM', 'Operation Total Void Control is authorized. (Location: Void Echo Chasm, Commander Drax) Exterminate all void signatures in the chasm. The Hegemony does not share territory.', '{"npc_id": "npc_hegemony_commander", "name": "Commander Drax", "location": "VOID_ECHO_CHASM"}'::jsonb, '{"min_level": 51, "reputation_required": 3000, "required_quests": ["fq_iron_051"]}'::jsonb, '[{"type": "kill", "target": "VOID_REAVER", "count": 8, "desc": "Exterminate Void Reavers.", "description": "Defeat Void Reaver (x8)."}, {"type": "kill", "target": "AETHEL_VOID_CHANNELER", "count": 5, "desc": "Exterminate Void Channelers.", "description": "Defeat Aethel Void Channeler (x5)."}]'::jsonb, '{"exp": 4500, "currency": 2200, "crd": 1100, "rep": 1500, "items": [{"item_id": "void_core", "quantity": 3}], "reputation": 50}'::jsonb, false, false, 'fq_iron_053', false, NULL, NULL, NULL, 'quest_iron.json', 51)
