values ('fq_iron_053', 'Void Stalker Execution', 'boss', 'S', 'IRON_HEGEMONY', 'VOID_ECHO_CHASM', 'A Void Stalker has been hunting our soldiers. (Location: Void Echo Chasm, Commander Drax) This insult to Hegemony strength will be answered with execution.', '{"npc_id": "npc_hegemony_commander", "name": "Commander Drax", "location": "VOID_ECHO_CHASM"}'::jsonb, '{"min_level": 52, "reputation_required": 3060, "required_quests": ["fq_iron_052"]}'::jsonb, '[{"type": "kill", "target": "VOID_STALKER", "count": 1, "desc": "Execute the Void Stalker.", "description": "Defeat Void Stalker (x1)."}, {"type": "collect", "target": "core_fragment", "count": 1, "desc": "Recover fallen soldiers'' identification.", "description": "Collect core fragment (x1). [Item: Core Fragment]"}]'::jsonb, '{"exp": 5500, "currency": 2800, "crd": 1400, "rep": 1800, "items": [{"item_id": "entropy_core", "quantity": 1}], "reputation": 50}'::jsonb, false, false, 'fq_iron_054', false, NULL, NULL, NULL, 'quest_iron.json', 52)
