values ('fq_iron_054', 'Temporal Breach', 'boss', 'S', 'IRON_HEGEMONY', 'VOID_ECHO_CHASM', 'Chrono Wraiths create temporal breaches that trap our troops. (Location: Void Echo Chasm, Commander Drax) Close the breaches with extreme prejudice.', '{"npc_id": "npc_hegemony_commander", "name": "Commander Drax", "location": "VOID_ECHO_CHASM"}'::jsonb, '{"min_level": 53, "reputation_required": 3120, "required_quests": ["fq_iron_053"]}'::jsonb, '[{"type": "kill", "target": "CHRONO_WRAITH", "count": 3, "desc": "Destroy Chrono Wraiths and close breaches.", "description": "Defeat Chrono Wraith (x3)."}, {"type": "collect", "target": "monster_material", "count": 3, "desc": "Confirm breach closures.", "description": "Collect monster material (x3). [Item: Monster Material]"}]'::jsonb, '{"exp": 6500, "currency": 3200, "crd": 1600, "rep": 2000, "items": [{"item_id": "quantum_distortion_stone", "quantity": 2}], "reputation": 50}'::jsonb, false, false, 'fq_iron_055', false, NULL, NULL, NULL, 'quest_iron.json', 53)
