values ('fq_iron_055', 'Heart Assault', 'hunt', 'S', 'IRON_HEGEMONY', 'SHATTERED_HEART', 'Full assault on the Shattered Heart. Enemy Reaver battalions are dug in. Dig them out. Quest giver: Commander Drax at Bastion Core Command Bunker.', '{"npc_id": "npc_hegemony_commander", "name": "Commander Drax", "location": "SHATTERED_HEART"}'::jsonb, '{"min_level": 54, "reputation_required": 3180, "required_quests": ["fq_iron_054"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_ABYSSAL_REAVER", "count": 10, "desc": "Assault Reaver defensive positions.", "description": "Defeat Aethel Abyssal Reaver (x10)."}, {"type": "kill", "target": "VOID_REAVER", "count": 6, "desc": "Clear Void Reaver support units.", "description": "Defeat Void Reaver (x6)."}]'::jsonb, '{"exp": 5000, "currency": 2500, "crd": 1250, "rep": 1700, "items": [{"item_id": "event_horizon_fragment", "quantity": 3}], "reputation": 50}'::jsonb, false, false, 'fq_iron_056', false, NULL, NULL, NULL, 'quest_iron.json', 54)
