values ('fq_iron_057', 'Tyrant Battery', 'boss', 'S', 'IRON_HEGEMONY', 'SHATTERED_HEART', 'Crystal Tyrants form a defensive battery in the Heart. (Location: Shattered Heart, Commander Drax) Silence their guns.', '{"npc_id": "npc_hegemony_commander", "name": "Commander Drax", "location": "SHATTERED_HEART"}'::jsonb, '{"min_level": 56, "reputation_required": 3300, "required_quests": ["fq_iron_056"]}'::jsonb, '[{"type": "kill", "target": "CRYSTAL_TYRANT", "count": 2, "desc": "Silence the Tyrant battery.", "description": "Defeat Crystal Tyrant (x2)."}, {"type": "collect", "target": "monster_material", "count": 1, "desc": "Report battery destruction.", "description": "Collect monster material (x1). [Item: Monster Material]"}]'::jsonb, '{"exp": 7200, "currency": 3600, "crd": 1800, "rep": 2300, "items": [{"item_id": "quantum_distortion_stone", "quantity": 2}], "reputation": 50}'::jsonb, false, false, 'fq_iron_058', false, NULL, NULL, NULL, 'quest_iron.json', 56)
