values ('fq_iron_058', 'Harbinger Beachhead', 'story', 'S', 'IRON_HEGEMONY', 'VOID_ECHO_CHASM', 'The Abyss Harbinger is the enemy high command. (Location: Void Echo Chasm, Commander Drax) Establish a beachhead for the final assault.', '{"npc_id": "npc_hegemony_commander", "name": "Commander Drax", "location": "VOID_ECHO_CHASM"}'::jsonb, '{"min_level": 57, "reputation_required": 180, "required_quests": ["fq_iron_057"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_ABYSSAL_REAVER", "count": 6, "desc": "Clear the beachhead zone.", "description": "Defeat Aethel Abyssal Reaver (x6)."}, {"type": "kill", "target": "CHRONO_WRAITH", "count": 1, "desc": "Eliminate Chrono Wraith defending the beachhead.", "description": "Defeat Chrono Wraith (x1)."}, {"type": "collect", "target": "raw_aethel_fragment", "count": 1, "desc": "Confirm beachhead established.", "description": "Collect raw aethel fragment (x1). [Item: Raw Aethel Fragment]"}]'::jsonb, '{"exp": 7500, "currency": 3800, "crd": 1900, "rep": 2400, "items": [{"item_id": "event_horizon_fragment_l", "quantity": 1}], "reputation": 50}'::jsonb, false, false, 'fq_iron_059', false, NULL, NULL, NULL, 'quest_iron.json', 57)
