values ('fq_iron_059', 'Fragmenter Front', 'boss', 'S', 'IRON_HEGEMONY', 'VOID_ECHO_CHASM', 'Soul Fragmenters form the enemy''s psychological warfare front. (Location: Void Echo Chasm, Commander Drax) Break their front.', '{"npc_id": "npc_hegemony_commander", "name": "Commander Drax", "location": "VOID_ECHO_CHASM"}'::jsonb, '{"min_level": 58, "reputation_required": 3420, "required_quests": ["fq_iron_058"]}'::jsonb, '[{"type": "kill", "target": "SOUL_FRAGMENTER", "count": 3, "desc": "Break the Fragmenter front.", "description": "Defeat Soul Fragmenter (x3)."}, {"type": "kill", "target": "VOID_STALKER", "count": 1, "desc": "Eliminate the Stalker commanding them.", "description": "Defeat Void Stalker (x1)."}]'::jsonb, '{"exp": 8000, "currency": 4000, "crd": 2000, "rep": 2500, "items": [{"item_id": "brainwave_oscillator", "quantity": 2}], "reputation": 50}'::jsonb, false, false, 'fq_iron_060', false, NULL, NULL, NULL, 'quest_iron.json', 58)
