values ('fq_iron_060', 'Harbinger''s Defeat', 'boss', 'S', 'IRON_HEGEMONY', 'VOID_ECHO_CHASM', 'FINAL ASSAULT ON THE ABYSS. (Location: Void Echo Chasm, Commander Drax) The Abyss Harbinger is the enemy commander. Destroy it and claim total victory over the Void. THE HEGEMONY CONTROLS ALL.', '{"npc_id": "npc_hegemony_commander", "name": "Commander Drax", "location": "VOID_ECHO_CHASM"}'::jsonb, '{"min_level": 59, "reputation_required": 3480, "required_quests": ["fq_iron_059"]}'::jsonb, '[{"type": "kill", "target": "ABYSS_HARBINGER", "count": 1, "desc": "DEFEAT THE ABYSS HARBINGER.", "description": "Defeat Abyss Harbinger (x1)."}, {"type": "collect", "target": "abyss_fragment", "count": 1, "desc": "Claim the Harbinger''s battle standard for the Bastion.", "description": "Collect abyss fragment (x1). [Item: Abyss Fragment]"}]'::jsonb, '{"exp": 15000, "currency": 7500, "crd": 3750, "rep": 5000, "items": [{"item_id": "void_core", "quantity": 5}, {"item_id": "event_horizon_fragment_l", "quantity": 2}, {"item_id": "con_elite_recovery_pack", "quantity": 10}], "reputation": 50}'::jsonb, false, false, 'fq_iron_061', false, NULL, NULL, NULL, 'quest_iron.json', 59)
