values ('fq_iron_061', 'Stabilizing the Front', 'exploration', 'S', 'IRON_HEGEMONY', 'SEVERANCE_FAULTLINE', 'The Severance Faultline threatens planetary stability. The Hegemony does not negotiate with nature — we conquer it. Quest giver: Commander Drax at Bastion Core Command Bunker.', '{"npc_id": "npc_hegemony_commander", "name": "Commander Drax", "location": "SEVERANCE_FAULTLINE"}'::jsonb, '{"min_level": 60, "reputation_required": 3540, "required_quests": ["fq_iron_060"]}'::jsonb, '[{"type": "travel", "target": "SEVERANCE_FAULTLINE", "count": 1, "desc": "Enter the Severance Faultline.", "description": "Travel to SEVERANCE FAULTLINE. (Travel to: Severance Faultline, Shattered Heart)"}, {"type": "collect", "target": "abyss_fragment", "count": 3, "desc": "Collect fault stability readings.", "description": "Collect abyss fragment (x3). [Item: Abyss Fragment]"}]'::jsonb, '{"exp": 5000, "currency": 2500, "crd": 1250, "rep": 1600, "items": [{"item_id": "stabilizer_gyro_unit", "quantity": 2}], "reputation": 50}'::jsonb, false, false, 'fq_iron_062', false, NULL, NULL, NULL, 'quest_iron.json', 60)
