values ('fq_iron_062', 'Carapace Armor', 'hunt', 'S', 'IRON_HEGEMONY', 'SEVERANCE_FAULTLINE', 'Aethel Iron Carapaces have armor that rivals Hegemony steel. (Location: Severance Faultline, Commander Drax) Destroy them and study their composition.', '{"npc_id": "npc_hegemony_commander", "name": "Commander Drax", "location": "SEVERANCE_FAULTLINE"}'::jsonb, '{"min_level": 61, "reputation_required": 3600, "required_quests": ["fq_iron_061"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_IRON_CARAPACE", "count": 8, "desc": "Destroy Iron Carapaces.", "description": "Defeat Aethel Iron Carapace (x8)."}, {"type": "collect", "target": "crystal_core", "count": 3, "desc": "Collect armor samples for the forges.", "description": "Collect crystal core (x3). [Item: Crystal Core]"}]'::jsonb, '{"exp": 5200, "currency": 2600, "crd": 1300, "rep": 1700, "items": [{"item_id": "gravity_well_core", "quantity": 1}], "reputation": 50}'::jsonb, false, false, 'fq_iron_063', false, NULL, NULL, NULL, 'quest_iron.json', 61)
