values ('fq_iron_063', 'Tyrant Position', 'boss', 'S', 'IRON_HEGEMONY', 'SEVERANCE_FAULTLINE', 'Crystal Tyrants have taken positions along the fault. (Location: Severance Faultline, Commander Drax) They are obstacles. Remove them.', '{"npc_id": "npc_hegemony_commander", "name": "Commander Drax", "location": "SEVERANCE_FAULTLINE"}'::jsonb, '{"min_level": 62, "reputation_required": 3660, "required_quests": ["fq_iron_062"]}'::jsonb, '[{"type": "kill", "target": "CRYSTAL_TYRANT", "count": 2, "desc": "Remove Tyrant positions.", "description": "Defeat Crystal Tyrant (x2)."}, {"type": "collect", "target": "core_fragment", "count": 2, "desc": "Confirm positions cleared.", "description": "Collect core fragment (x2). [Item: Core Fragment]"}]'::jsonb, '{"exp": 6000, "currency": 3000, "crd": 1500, "rep": 2000, "items": [{"item_id": "quantum_distortion_stone", "quantity": 2}], "reputation": 50}'::jsonb, false, false, 'fq_iron_064', false, NULL, NULL, NULL, 'quest_iron.json', 62)
