values ('fq_iron_064', 'Jotunn Blockade', 'boss', 'S', 'IRON_HEGEMONY', 'SEVERANCE_FAULTLINE', 'Gigantic Jotunns blockade the main advance route. (Location: Severance Faultline, Commander Drax) Break through. Nothing blocks the Hegemony advance.', '{"npc_id": "npc_hegemony_commander", "name": "Commander Drax", "location": "SEVERANCE_FAULTLINE"}'::jsonb, '{"min_level": 63, "reputation_required": 3720, "required_quests": ["fq_iron_063"]}'::jsonb, '[{"type": "kill", "target": "GIGANTIC_JOTUNN", "count": 3, "desc": "Break the Jotunn blockade.", "description": "Defeat Gigantic Jotunn (x3)."}, {"type": "collect", "target": "monster_material", "count": 1, "desc": "Confirm advance route open.", "description": "Collect monster material (x1). [Item: Monster Material]"}]'::jsonb, '{"exp": 6500, "currency": 3300, "crd": 1650, "rep": 2100, "items": [{"item_id": "titan_core", "quantity": 2}], "reputation": 50}'::jsonb, false, false, 'fq_iron_065', false, NULL, NULL, NULL, 'quest_iron.json', 63)
