values ('fq_iron_065', 'Power Core', 'exploration', 'S', 'IRON_HEGEMONY', 'AETHEL_SIPHON_CORE', 'The Aethel Siphon Core is the planet''s power source. The Hegemony will control the power. Enter and secure. Quest giver: Commander Drax at Bastion Core Command Bunker.', '{"npc_id": "npc_hegemony_commander", "name": "Commander Drax", "location": "AETHEL_SIPHON_CORE"}'::jsonb, '{"min_level": 64, "reputation_required": 3780, "required_quests": ["fq_iron_064"]}'::jsonb, '[{"type": "travel", "target": "AETHEL_SIPHON_CORE", "count": 1, "desc": "Enter the Aethel Siphon Core.", "description": "Travel to AETHEL SIPHON CORE. (Travel to: Aethel Siphon Core, Shattered Heart)"}, {"type": "collect", "target": "monster_material", "count": 2, "desc": "Take power readings.", "description": "Collect monster material (x2). [Item: Monster Material]"}]'::jsonb, '{"exp": 5500, "currency": 2800, "crd": 1400, "rep": 1800, "items": [{"item_id": "power_regulator_core", "quantity": 1}], "reputation": 50}'::jsonb, false, false, 'fq_iron_066', false, NULL, NULL, NULL, 'quest_iron.json', 64)
