values ('fq_iron_066', 'Core Purge', 'hunt', 'S', 'IRON_HEGEMONY', 'AETHEL_SIPHON_CORE', 'Hostile entities infest the Core. (Location: Aethel Siphon Core, Commander Drax) Purge them. The Core must be secure for Hegemony power operations.', '{"npc_id": "npc_hegemony_commander", "name": "Commander Drax", "location": "AETHEL_SIPHON_CORE"}'::jsonb, '{"min_level": 65, "reputation_required": 3840, "required_quests": ["fq_iron_065"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_ABYSSAL_REAVER", "count": 8, "desc": "Purge hostile entities from the Core.", "description": "Defeat Aethel Abyssal Reaver (x8)."}, {"type": "kill", "target": "AETHEL_VOID_CHANNELER", "count": 5, "desc": "Eliminate all Channelers.", "description": "Defeat Aethel Void Channeler (x5)."}]'::jsonb, '{"exp": 5800, "currency": 2900, "crd": 1450, "rep": 1900, "items": [{"item_id": "aethel_core_shard", "quantity": 3}], "reputation": 50}'::jsonb, false, false, 'fq_iron_067', false, NULL, NULL, NULL, 'quest_iron.json', 65)
