values ('fq_iron_067', 'Behemoth Defense', 'boss', 'S', 'IRON_HEGEMONY', 'AETHEL_SIPHON_CORE', 'Corrupted Behemoths assault the Core conduits. (Location: Aethel Siphon Core, Commander Drax) Defend the Core. Hegemony never surrenders a position.', '{"npc_id": "npc_hegemony_commander", "name": "Commander Drax", "location": "AETHEL_SIPHON_CORE"}'::jsonb, '{"min_level": 66, "reputation_required": 3900, "required_quests": ["fq_iron_066"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_CORRUPTED_BEHEMOTH", "count": 3, "desc": "Defend against Behemoth assault.", "description": "Defeat Aethel Corrupted Behemoth (x3)."}, {"type": "collect", "target": "crystal_core", "count": 1, "desc": "Report successful defense.", "description": "Collect crystal core (x1). [Item: Crystal Core]"}]'::jsonb, '{"exp": 6200, "currency": 3100, "crd": 1550, "rep": 2000, "items": [{"item_id": "corrupted_synapse_cluster", "quantity": 2}], "reputation": 50}'::jsonb, false, false, 'fq_iron_068', false, NULL, NULL, NULL, 'quest_iron.json', 66)
