values ('fq_iron_068', 'Rift Patrol', 'hunt', 'S', 'IRON_HEGEMONY', 'AETHEL_SIPHON_CORE', 'Rift Stalkers use micro-rifts for ambush tactics. (Location: Aethel Siphon Core, Commander Drax) Counter-ambush them. Hegemony soldiers do not get ambushed.', '{"npc_id": "npc_hegemony_commander", "name": "Commander Drax", "location": "AETHEL_SIPHON_CORE"}'::jsonb, '{"min_level": 67, "reputation_required": 3960, "required_quests": ["fq_iron_067"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_RIFT_STALKER", "count": 6, "desc": "Counter-ambush Rift Stalkers.", "description": "Defeat Aethel Rift Stalker (x6)."}, {"type": "collect", "target": "rift_claw_fragment", "count": 1, "desc": "Confirm patrol route sweep.", "description": "Collect rift claw fragment (x1). [Item: Rift Claw Fragment]"}]'::jsonb, '{"exp": 6400, "currency": 3200, "crd": 1600, "rep": 2100, "items": [{"item_id": "dark_energy_fragment", "quantity": 3}], "reputation": 50}'::jsonb, false, false, 'fq_iron_069', false, NULL, NULL, NULL, 'quest_iron.json', 67)
