values ('fq_iron_071', 'The Hegemony Forge', 'exploration', 'S', 'IRON_HEGEMONY', 'PRIMA_MATERIA_FORGE', 'The Prima Materia Forge will become the Hegemony''s primary weapons factory. Secure it for mass production. Quest giver: Foreman Brigg at Titan Assembly Yard Command Post.', '{"npc_id": "npc_assembly_foreman", "name": "Foreman Brigg", "location": "PRIMA_MATERIA_FORGE"}'::jsonb, '{"min_level": 70, "reputation_required": 4140, "required_quests": ["fq_iron_070"]}'::jsonb, '[{"type": "travel", "target": "PRIMA_MATERIA_FORGE", "count": 1, "desc": "Enter the Prima Materia Forge.", "description": "Travel to PRIMA MATERIA FORGE. (Travel to: Prima Materia Forge, Shattered Heart)"}, {"type": "collect", "target": "core_fragment", "count": 2, "desc": "Assess Forge infrastructure.", "description": "Collect core fragment (x2). [Item: Core Fragment]"}]'::jsonb, '{"exp": 6000, "currency": 3000, "crd": 1500, "rep": 2000, "items": [{"item_id": "raw_aethel_core", "quantity": 2}], "reputation": 50}'::jsonb, false, false, 'fq_iron_072', false, NULL, NULL, NULL, 'quest_iron.json', 70)
