values ('fq_iron_072', 'Defense Neutralization', 'hunt', 'S', 'IRON_HEGEMONY', 'PRIMA_MATERIA_FORGE', 'Ancient Forge defenses still operate. (Location: Prima Materia Forge, Commander Drax) Neutralize them. The Forge serves the Hegemony now.', '{"npc_id": "npc_hegemony_commander", "name": "Commander Drax", "location": "PRIMA_MATERIA_FORGE"}'::jsonb, '{"min_level": 71, "reputation_required": 4200, "required_quests": ["fq_iron_071"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_IRON_CARAPACE", "count": 8, "desc": "Neutralize Forge defense systems.", "description": "Defeat Aethel Iron Carapace (x8)."}, {"type": "collect", "target": "carapace_fragment", "count": 2, "desc": "Confirm defense overrides.", "description": "Collect carapace fragment (x2). [Item: Carapace Fragment]"}]'::jsonb, '{"exp": 6200, "currency": 3100, "crd": 1550, "rep": 2100, "items": [{"item_id": "rusted_cybernetic_arm", "quantity": 2}], "reputation": 50}'::jsonb, false, false, 'fq_iron_073', false, NULL, NULL, NULL, 'quest_iron.json', 71)
