values ('fq_iron_073', 'Forge Purification', 'boss', 'S', 'IRON_HEGEMONY', 'PRIMA_MATERIA_FORGE', 'Corrupted Behemoths contaminate the Forge. (Location: Prima Materia Forge, Foreman Brigg) Purify the facility. Hegemony weapons require pure materials.', '{"npc_id": "npc_assembly_foreman", "name": "Foreman Brigg", "location": "PRIMA_MATERIA_FORGE"}'::jsonb, '{"min_level": 72, "reputation_required": 4260, "required_quests": ["fq_iron_072"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_CORRUPTED_BEHEMOTH", "count": 3, "desc": "Purify the Forge of Behemoths.", "description": "Defeat Aethel Corrupted Behemoth (x3)."}, {"type": "collect", "target": "crystal_core", "count": 1, "desc": "Confirm contamination cleared.", "description": "Collect crystal core (x1). [Item: Crystal Core]"}]'::jsonb, '{"exp": 6500, "currency": 3300, "crd": 1650, "rep": 2200, "items": [{"item_id": "neural_disruptor_module", "quantity": 1}], "reputation": 50}'::jsonb, false, false, 'fq_iron_074', false, NULL, NULL, NULL, 'quest_iron.json', 72)
