values ('fq_iron_074', 'Abyssal Purge', 'hunt', 'S', 'IRON_HEGEMONY', 'PRIMA_MATERIA_FORGE', 'Abyssal forces attempt to claim the Forge. (Location: Prima Materia Forge, Commander Drax) Purge them with maximum force.', '{"npc_id": "npc_hegemony_commander", "name": "Commander Drax", "location": "PRIMA_MATERIA_FORGE"}'::jsonb, '{"min_level": 73, "reputation_required": 4320, "required_quests": ["fq_iron_073"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_ABYSSAL_REAVER", "count": 8, "desc": "Purge Abyssal forces.", "description": "Defeat Aethel Abyssal Reaver (x8)."}, {"type": "kill", "target": "AETHEL_VOID_CHANNELER", "count": 5, "desc": "Eliminate command units.", "description": "Defeat Aethel Void Channeler (x5)."}]'::jsonb, '{"exp": 6800, "currency": 3400, "crd": 1700, "rep": 2300, "items": [{"item_id": "aethel_fragment", "quantity": 3}], "reputation": 50}'::jsonb, false, false, 'fq_iron_075', false, NULL, NULL, NULL, 'quest_iron.json', 73)
