values ('fq_iron_075', 'Jotunn Foundry', 'boss', 'S', 'IRON_HEGEMONY', 'PRIMA_MATERIA_FORGE', 'Jotunns use the Forge''s heat as weapons. (Location: Prima Materia Forge, Foreman Brigg) Disarm and destroy them. The Forge''s fire belongs to the Hegemony.', '{"npc_id": "npc_assembly_foreman", "name": "Foreman Brigg", "location": "PRIMA_MATERIA_FORGE"}'::jsonb, '{"min_level": 74, "reputation_required": 4380, "required_quests": ["fq_iron_074"]}'::jsonb, '[{"type": "kill", "target": "GIGANTIC_JOTUNN", "count": 3, "desc": "Destroy Jotunn forge-holders.", "description": "Defeat Gigantic Jotunn (x3)."}, {"type": "collect", "target": "core_fragment", "count": 1, "desc": "Secure forge heat control.", "description": "Collect core fragment (x1). [Item: Core Fragment]"}]'::jsonb, '{"exp": 7200, "currency": 3600, "crd": 1800, "rep": 2400, "items": [{"item_id": "titan_core", "quantity": 2}], "reputation": 50}'::jsonb, false, false, 'fq_iron_076', false, NULL, NULL, NULL, 'quest_iron.json', 74)
