values ('fq_iron_076', 'Apex Production', 'hunt', 'S', 'IRON_HEGEMONY', 'PRIMA_MATERIA_FORGE', 'Operation Apex Production begins. (Location: Prima Materia Forge, Foreman Brigg) The Forge will mass-produce Hegemony Apex-class weapons. Secure the production floor.', '{"npc_id": "npc_assembly_foreman", "name": "Foreman Brigg", "location": "PRIMA_MATERIA_FORGE"}'::jsonb, '{"min_level": 75, "reputation_required": 4440, "required_quests": ["fq_iron_075"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_VOID_CHANNELER", "count": 6, "desc": "Secure the production floor.", "description": "Defeat Aethel Void Channeler (x6)."}, {"type": "collect", "target": "raw_aethel_fragment", "count": 1, "desc": "Activate the production line.", "description": "Collect raw aethel fragment (x1). [Item: Raw Aethel Fragment]"}]'::jsonb, '{"exp": 7500, "currency": 3800, "crd": 1900, "rep": 2500, "items": [{"item_id": "power_regulator_core", "quantity": 2}], "reputation": 50}'::jsonb, false, false, 'fq_iron_077', false, NULL, NULL, NULL, 'quest_iron.json', 75)
