values ('fq_iron_077', 'Automaton Override', 'boss', 'S', 'IRON_HEGEMONY', 'PRIMA_MATERIA_FORGE', 'Titan Forge Automatons resist our control. (Location: Prima Materia Forge, Foreman Brigg) Override them — by any means necessary.', '{"npc_id": "npc_assembly_foreman", "name": "Foreman Brigg", "location": "PRIMA_MATERIA_FORGE"}'::jsonb, '{"min_level": 76, "reputation_required": 4500, "required_quests": ["fq_iron_076"]}'::jsonb, '[{"type": "kill", "target": "TITAN_FORGE_AUTOMATON", "count": 3, "desc": "Override Titan Forge Automatons.", "description": "Defeat Titan Forge Automaton (x3)."}, {"type": "collect", "target": "monster_material", "count": 1, "desc": "Confirm override protocol active.", "description": "Collect monster material (x1). [Item: Monster Material]"}]'::jsonb, '{"exp": 8000, "currency": 4000, "crd": 2000, "rep": 2600, "items": [{"item_id": "processor_cooling_unit", "quantity": 2}], "reputation": 50}'::jsonb, false, false, 'fq_iron_078', false, NULL, NULL, NULL, 'quest_iron.json', 76)
