values ('fq_iron_078', 'Proto Core Recycling', 'boss', 'S', 'IRON_HEGEMONY', 'PRIMA_MATERIA_FORGE', 'Titan Proto Cores are failed Titans — but their materials are valuable. (Location: Prima Materia Forge, Foreman Brigg) Recycle them into Hegemony steel.', '{"npc_id": "npc_assembly_foreman", "name": "Foreman Brigg", "location": "PRIMA_MATERIA_FORGE"}'::jsonb, '{"min_level": 77, "reputation_required": 4560, "required_quests": ["fq_iron_077"]}'::jsonb, '[{"type": "kill", "target": "TITAN_PROTO_CORE", "count": 2, "desc": "Recycle Titan Proto Cores.", "description": "Defeat Titan Proto Core (x2)."}, {"type": "collect", "target": "titan_core", "count": 1, "desc": "Process recycled Titan steel.", "description": "Collect titan core (x1). [Item: Titan Core]"}]'::jsonb, '{"exp": 9000, "currency": 4500, "crd": 2250, "rep": 2800, "items": [{"item_id": "titan_core", "quantity": 2}], "reputation": 50}'::jsonb, false, false, 'fq_iron_079', false, NULL, NULL, NULL, 'quest_iron.json', 77)
