values ('fq_iron_079', 'Supreme General Trial', 'story', 'S', 'IRON_HEGEMONY', 'PRIMA_MATERIA_FORGE', 'The final trial before Supreme General rank. (Location: Prima Materia Forge, Commander Drax) Defeat both Titan and Harbinger in a single campaign. Show the galaxy what Hegemony steel can do.', '{"npc_id": "npc_hegemony_commander", "name": "Commander Drax", "location": "PRIMA_MATERIA_FORGE"}'::jsonb, '{"min_level": 78, "reputation_required": 280, "required_quests": ["fq_iron_078"]}'::jsonb, '[{"type": "kill", "target": "GRAVITY_TITAN", "count": 1, "desc": "Defeat the Gravity Titan.", "description": "Defeat Gravity Titan (x1)."}, {"type": "kill", "target": "ABYSS_HARBINGER", "count": 1, "desc": "Defeat the Abyss Harbinger.", "description": "Defeat Abyss Harbinger (x1)."}]'::jsonb, '{"exp": 12000, "currency": 6000, "crd": 3000, "rep": 4000, "items": [{"item_id": "drake_heart", "quantity": 1}, {"item_id": "titan_core", "quantity": 2}, {"item_id": "void_core", "quantity": 3}], "reputation": 50}'::jsonb, false, false, 'fq_iron_080', false, NULL, NULL, NULL, 'quest_iron.json', 78)
