values ('fq_iron_080', 'Supreme General', 'story', 'S', 'IRON_HEGEMONY', 'BASTION_CORE', 'High Commander Varkas himself will pin the Supreme General insignia on your chest. (Location: Bastion Core, Commander Drax) Return to the Bastion. The Hegemony salutes you.', '{"npc_id": "npc_hegemony_commander", "name": "Commander Drax", "location": "BASTION_CORE"}'::jsonb, '{"min_level": 79, "reputation_required": 330, "required_quests": ["fq_iron_079"]}'::jsonb, '[{"type": "travel", "target": "BASTION_CORE", "count": 1, "desc": "Return to the Bastion.", "description": "Travel to BASTION CORE. (Travel to: Bastion Core)"}, {"type": "collect", "target": "core_fragment", "count": 1, "desc": "Receive the Supreme General insignia.", "description": "Collect core fragment (x1). [Item: Core Fragment]"}]'::jsonb, '{"exp": 10000, "currency": 5000, "crd": 2500, "rep": 3500, "items": [{"item_id": "con_elite_recovery_pack", "quantity": 10}, {"item_id": "astral_phase_crystal_pure", "quantity": 3}], "reputation": 50}'::jsonb, false, false, 'fq_iron_081', false, NULL, NULL, NULL, 'quest_iron.json', 79)
