values ('fq_iron_081', 'Apex Predator', 'story', 'S', 'IRON_HEGEMONY', 'HIDDEN_AETHELGARDIAN_CITY', 'The Hidden Aethelgardian City contains Precursor weapons technology. The Hegemony will not allow any faction to claim it first. Quest giver: Commander Drax at Bastion Core Command Bunker.', '{"npc_id": "npc_hegemony_commander", "name": "Commander Drax", "location": "HIDDEN_AETHELGARDIAN_CITY"}'::jsonb, '{"min_level": 80, "reputation_required": 380, "required_quests": ["fq_iron_080"]}'::jsonb, '[{"type": "travel", "target": "HIDDEN_AETHELGARDIAN_CITY", "count": 1, "desc": "Enter the Hidden Aethelgardian City.", "description": "Travel to HIDDEN AETHELGARDIAN CITY. (Travel to: Hidden Aethelgardian City)"}, {"type": "collect", "target": "slime_core", "count": 3, "desc": "Recover Precursor weapons data.", "description": "Collect slime core (x3). [Item: Slime Core]"}]'::jsonb, '{"exp": 8000, "currency": 4000, "crd": 2000, "rep": 2500, "items": [{"item_id": "aethel_core_shard", "quantity": 5}], "reputation": 50}'::jsonb, false, false, 'fq_iron_082', false, NULL, NULL, NULL, 'quest_iron.json', 80)
