values ('fq_iron_082', 'City Garrison', 'hunt', 'S', 'IRON_HEGEMONY', 'HIDDEN_AETHELGARDIAN_CITY', 'The City has automated defenses. (Location: Hidden Aethelgardian City, Commander Drax) Destroy them. Hegemony takes what it wants.', '{"npc_id": "npc_hegemony_commander", "name": "Commander Drax", "location": "HIDDEN_AETHELGARDIAN_CITY"}'::jsonb, '{"min_level": 81, "reputation_required": 4800, "required_quests": ["fq_iron_081"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_RIFT_STALKER", "count": 8, "desc": "Destroy city defense systems.", "description": "Defeat Aethel Rift Stalker (x8)."}, {"type": "collect", "target": "rift_claw_fragment", "count": 3, "desc": "Confirm city sectors secured.", "description": "Collect rift claw fragment (x3). [Item: Rift Claw Fragment]"}]'::jsonb, '{"exp": 8500, "currency": 4200, "crd": 2100, "rep": 2700, "items": [{"item_id": "quantum_distortion_stone", "quantity": 2}], "reputation": 50}'::jsonb, false, false, 'fq_iron_083', false, NULL, NULL, NULL, 'quest_iron.json', 81)
