values ('fq_iron_083', 'Weapons Cache', 'collect', 'S', 'IRON_HEGEMONY', 'HIDDEN_AETHELGARDIAN_CITY', 'The City holds Precursor weapons caches. (Location: Hidden Aethelgardian City, Commander Drax) Secure them all for the Hegemony arsenal.', '{"npc_id": "npc_hegemony_commander", "name": "Commander Drax", "location": "HIDDEN_AETHELGARDIAN_CITY"}'::jsonb, '{"min_level": 82, "reputation_required": 4860, "required_quests": ["fq_iron_082"]}'::jsonb, '[{"type": "collect", "target": "void_channeler_core", "count": 5, "desc": "Secure weapons caches.", "description": "Collect void channeler core (x5). [Item: Void Channeler Core]"}, {"type": "kill", "target": "AETHEL_ABYSSAL_REAVER", "count": 4, "desc": "Eliminate forces drawn to the weapons.", "description": "Defeat Aethel Abyssal Reaver (x4)."}]'::jsonb, '{"exp": 8800, "currency": 4400, "crd": 2200, "rep": 2800, "items": [{"item_id": "memory_fragment_chip", "quantity": 3}], "reputation": 50}'::jsonb, false, false, 'fq_iron_084', false, NULL, NULL, NULL, 'quest_iron.json', 82)
