values ('fq_iron_084', 'Apex Drake Elimination', 'boss', 'S', 'IRON_HEGEMONY', 'SHATTERED_HEART', 'The Ashen Drake has evolved to Apex form. (Location: Shattered Heart, Commander Drax) Eliminate it. Hegemony tolerates no rivals — especially winged ones.', '{"npc_id": "npc_hegemony_commander", "name": "Commander Drax", "location": "SHATTERED_HEART"}'::jsonb, '{"min_level": 83, "reputation_required": 4920, "required_quests": ["fq_iron_083"]}'::jsonb, '[{"type": "kill", "target": "ASHEN_DRAKE", "count": 1, "desc": "Eliminate the Apex Ashen Drake.", "description": "Defeat Ashen Drake (x1)."}, {"type": "collect", "target": "drake_heart", "count": 1, "desc": "Verify Apex elimination.", "description": "Collect drake heart (x1). [Item: Drake Heart]"}]'::jsonb, '{"exp": 12000, "currency": 6000, "crd": 3000, "rep": 4000, "items": [{"item_id": "drake_heart", "quantity": 3}, {"item_id": "ancient_scale", "quantity": 3}], "reputation": 50}'::jsonb, false, false, 'fq_iron_085', false, NULL, NULL, NULL, 'quest_iron.json', 83)
