values ('fq_iron_085', 'Apex Harbinger Destruction', 'boss', 'S', 'IRON_HEGEMONY', 'VOID_ECHO_CHASM', 'The Abyss Harbinger has been reborn. (Location: Void Echo Chasm, Commander Drax) Destroy it again. And again if necessary. Hegemony victory is permanent.', '{"npc_id": "npc_hegemony_commander", "name": "Commander Drax", "location": "VOID_ECHO_CHASM"}'::jsonb, '{"min_level": 84, "reputation_required": 4980, "required_quests": ["fq_iron_084"]}'::jsonb, '[{"type": "kill", "target": "ABYSS_HARBINGER", "count": 1, "desc": "Destroy the Apex Abyss Harbinger.", "description": "Defeat Abyss Harbinger (x1)."}, {"type": "collect", "target": "abyss_fragment", "count": 1, "desc": "Verify permanent destruction.", "description": "Collect abyss fragment (x1). [Item: Abyss Fragment]"}]'::jsonb, '{"exp": 13000, "currency": 6500, "crd": 3250, "rep": 4200, "items": [{"item_id": "void_core", "quantity": 5}, {"item_id": "event_horizon_fragment_l", "quantity": 3}], "reputation": 50}'::jsonb, false, false, 'fq_iron_086', false, NULL, NULL, NULL, 'quest_iron.json', 84)
