values ('fq_iron_086', 'Apex Titan Fall', 'boss', 'S', 'IRON_HEGEMONY', 'CRADLE_EXPANSE', 'The Gravity Titan manifests once more. (Location: Cradle Expanse, Commander Drax) Hegemony response unchanged: destroy it. Again.', '{"npc_id": "npc_hegemony_commander", "name": "Commander Drax", "location": "CRADLE_EXPANSE"}'::jsonb, '{"min_level": 85, "reputation_required": 5040, "required_quests": ["fq_iron_085"]}'::jsonb, '[{"type": "kill", "target": "GRAVITY_TITAN", "count": 1, "desc": "Destroy the Apex Gravity Titan.", "description": "Defeat Gravity Titan (x1)."}, {"type": "collect", "target": "core_fragment", "count": 1, "desc": "Confirm Titan fall.", "description": "Collect core fragment (x1). [Item: Core Fragment]"}]'::jsonb, '{"exp": 14000, "currency": 7000, "crd": 3500, "rep": 4500, "items": [{"item_id": "titan_core", "quantity": 4}, {"item_id": "gravity_well_core", "quantity": 3}], "reputation": 50}'::jsonb, false, false, 'fq_iron_087', false, NULL, NULL, NULL, 'quest_iron.json', 85)
