values ('fq_iron_087', 'Tri-Threat Offensive', 'boss', 'S', 'IRON_HEGEMONY', 'PRIMA_MATERIA_FORGE', 'All three Apex entities — Drake, Titan, Harbinger. (Location: Prima Materia Forge, Commander Drax) The Hegemony will destroy them all in a single campaign. Triple offensive authorized.', '{"npc_id": "npc_hegemony_commander", "name": "Commander Drax", "location": "PRIMA_MATERIA_FORGE"}'::jsonb, '{"min_level": 86, "reputation_required": 5100, "required_quests": ["fq_iron_086"]}'::jsonb, '[{"type": "kill", "target": "ASHEN_DRAKE", "count": 1, "desc": "Destroy the Drake.", "description": "Defeat Ashen Drake (x1)."}, {"type": "kill", "target": "GRAVITY_TITAN", "count": 1, "desc": "Destroy the Titan.", "description": "Defeat Gravity Titan (x1)."}, {"type": "kill", "target": "ABYSS_HARBINGER", "count": 1, "desc": "Destroy the Harbinger.", "description": "Defeat Abyss Harbinger (x1)."}]'::jsonb, '{"exp": 20000, "currency": 10000, "crd": 5000, "rep": 6000, "items": [{"item_id": "drake_heart", "quantity": 2}, {"item_id": "titan_core", "quantity": 2}, {"item_id": "void_core", "quantity": 3}], "reputation": 50}'::jsonb, false, false, 'fq_iron_088', false, NULL, NULL, NULL, 'quest_iron.json', 86)
