values ('fq_iron_088', 'Core Command', 'exploration', 'S', 'IRON_HEGEMONY', 'AETHEL_SIPHON_CORE', 'The Aethel Siphon Core becomes Hegemony Central Command. Establish full military control of the planetary power grid. Quest giver: Commander Drax at Bastion Core Command Bunker.', '{"npc_id": "npc_hegemony_commander", "name": "Commander Drax", "location": "AETHEL_SIPHON_CORE"}'::jsonb, '{"min_level": 87, "reputation_required": 5160, "required_quests": ["fq_iron_087"]}'::jsonb, '[{"type": "travel", "target": "AETHEL_SIPHON_CORE", "count": 1, "desc": "Enter Core Command.", "description": "Travel to AETHEL SIPHON CORE. (Travel to: Aethel Siphon Core, Shattered Heart)"}, {"type": "collect", "target": "stinger_core", "count": 5, "desc": "Deploy command beacons.", "description": "Collect stinger core (x5). [Item: Stinger Core]"}]'::jsonb, '{"exp": 10000, "currency": 5000, "crd": 2500, "rep": 3200, "items": [{"item_id": "power_regulator_core", "quantity": 3}], "reputation": 50}'::jsonb, false, false, 'fq_iron_089', false, NULL, NULL, NULL, 'quest_iron.json', 87)
