values ('fq_iron_089', 'World Engine Subjugation', 'story', 'S', 'IRON_HEGEMONY', 'AETHEL_SIPHON_CORE', 'The World Engine can reshape Xylos. (Location: Aethel Siphon Core, Commander Drax) The Hegemony will make it our ultimate weapon. Secure it absolutely.', '{"npc_id": "npc_hegemony_commander", "name": "Commander Drax", "location": "AETHEL_SIPHON_CORE"}'::jsonb, '{"min_level": 88, "reputation_required": 430, "required_quests": ["fq_iron_088"]}'::jsonb, '[{"type": "collect", "target": "core_fragment", "count": 3, "desc": "Obtain Engine control codes.", "description": "Collect core fragment (x3). [Item: Core Fragment]"}, {"type": "kill", "target": "GIGANTIC_JOTUNN", "count": 2, "desc": "Destroy Jotunn guards.", "description": "Defeat Gigantic Jotunn (x2)."}]'::jsonb, '{"exp": 11000, "currency": 5500, "crd": 2750, "rep": 3500, "items": [{"item_id": "aethel_core_shard", "quantity": 5}], "reputation": 50}'::jsonb, false, false, 'fq_iron_090', false, NULL, NULL, NULL, 'quest_iron.json', 88)
