values ('fq_iron_090', 'Engine Activation', 'story', 'S', 'IRON_HEGEMONY', 'AETHEL_SIPHON_CORE', 'Activate the World Engine. (Location: Aethel Siphon Core, Commander Drax) This is the moment Hegemony dominance becomes absolute. Defend the activation at all costs.', '{"npc_id": "npc_hegemony_commander", "name": "Commander Drax", "location": "AETHEL_SIPHON_CORE"}'::jsonb, '{"min_level": 89, "reputation_required": 480, "required_quests": ["fq_iron_089"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_ABYSSAL_REAVER", "count": 10, "desc": "Defend Engine activation.", "description": "Defeat Aethel Abyssal Reaver (x10)."}, {"type": "kill", "target": "CRYSTAL_TYRANT", "count": 2, "desc": "Destroy Tyrant saboteurs.", "description": "Defeat Crystal Tyrant (x2)."}, {"type": "collect", "target": "monster_material", "count": 1, "desc": "Confirm Engine activation.", "description": "Collect monster material (x1). [Item: Monster Material]"}]'::jsonb, '{"exp": 13000, "currency": 6500, "crd": 3250, "rep": 4200, "items": [{"item_id": "resonanted_astral_phase_crystal", "quantity": 1}], "reputation": 50}'::jsonb, false, false, 'fq_iron_091', false, NULL, NULL, NULL, 'quest_iron.json', 89)
