values ('fq_iron_091', 'Final Purge', 'hunt', 'S', 'IRON_HEGEMONY', 'SEVERANCE_FAULTLINE', 'With the Engine online, remaining hostiles are flushed to the surface. (Location: Severance Faultline, Commander Drax) Execute the final purge at the Faultline.', '{"npc_id": "npc_hegemony_commander", "name": "Commander Drax", "location": "SEVERANCE_FAULTLINE"}'::jsonb, '{"min_level": 90, "reputation_required": 5340, "required_quests": ["fq_iron_090"]}'::jsonb, '[{"type": "kill", "target": "GIGANTIC_JOTUNN", "count": 5, "desc": "Execute Jotunns.", "description": "Defeat Gigantic Jotunn (x5)."}, {"type": "kill", "target": "AETHEL_IRON_CARAPACE", "count": 8, "desc": "Execute Carapaces.", "description": "Defeat Aethel Iron Carapace (x8)."}]'::jsonb, '{"exp": 10000, "currency": 5000, "crd": 2500, "rep": 3200, "items": [{"item_id": "stabilizer_gyro_unit", "quantity": 3}], "reputation": 50}'::jsonb, false, false, 'fq_iron_092', false, NULL, NULL, NULL, 'quest_iron.json', 90)
