values ('fq_iron_092', 'Void Annihilation', 'hunt', 'S', 'IRON_HEGEMONY', 'VOID_ECHO_CHASM', 'The Void is collapsing. (Location: Void Echo Chasm, Commander Drax) Annihilate the remaining void forces. The Hegemony will erase the Abyss from history.', '{"npc_id": "npc_hegemony_commander", "name": "Commander Drax", "location": "VOID_ECHO_CHASM"}'::jsonb, '{"min_level": 91, "reputation_required": 5400, "required_quests": ["fq_iron_091"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_ABYSSAL_REAVER", "count": 10, "desc": "Annihilate Abyssal forces.", "description": "Defeat Aethel Abyssal Reaver (x10)."}, {"type": "kill", "target": "VOID_REAVER", "count": 10, "desc": "Annihilate Void forces.", "description": "Defeat Void Reaver (x10)."}]'::jsonb, '{"exp": 11000, "currency": 5500, "crd": 2750, "rep": 3500, "items": [{"item_id": "void_core", "quantity": 5}], "reputation": 50}'::jsonb, false, false, 'fq_iron_093', false, NULL, NULL, NULL, 'quest_iron.json', 91)
