values ('fq_iron_093', 'Tyrant Extermination', 'boss', 'S', 'IRON_HEGEMONY', 'SHATTERED_HEART', 'Crystal Tyrants make their last stand. (Location: Shattered Heart, Commander Drax) Exterminate them. The Hegemony leaves no enemy standing.', '{"npc_id": "npc_hegemony_commander", "name": "Commander Drax", "location": "SHATTERED_HEART"}'::jsonb, '{"min_level": 92, "reputation_required": 5460, "required_quests": ["fq_iron_092"]}'::jsonb, '[{"type": "kill", "target": "CRYSTAL_TYRANT", "count": 3, "desc": "Exterminate Crystal Tyrants.", "description": "Defeat Crystal Tyrant (x3)."}, {"type": "collect", "target": "core_fragment", "count": 1, "desc": "Confirm extermination complete.", "description": "Collect core fragment (x1). [Item: Core Fragment]"}]'::jsonb, '{"exp": 12000, "currency": 6000, "crd": 3000, "rep": 4000, "items": [{"item_id": "quantum_distortion_stone", "quantity": 4}], "reputation": 50}'::jsonb, false, false, 'fq_iron_094', false, NULL, NULL, NULL, 'quest_iron.json', 92)
